const firmCategories=f=>f?(Array.isArray(f.categories)?f.categories:[f.category]).filter(Boolean):[];
const firmHasCategory=(f,category)=>firmCategories(f).includes(category);
const FOREX_NAMES=new Set(TRUSTPILOT_FIRMS.filter(f=>firmHasCategory(f,'forex')).map(f=>f.name));
const marketLabels={forex:'Forex',futures:'Futures',crypto:'Crypto'};
const marketLabel=()=>marketLabels[market]||'Forex';
const categoryTrustpilotFirms=()=>TRUSTPILOT_FIRMS.filter(f=>firmHasCategory(f,market));
const forexTrustpilotFirms=()=>categoryTrustpilotFirms();
const trustpilotFor=name=>TRUSTPILOT_FIRMS.find(f=>f.name===name)||null;
const firmInMarket=(name,category=market)=>firmHasCategory(trustpilotFor(name),category);
const trustpilotBadge=name=>{const f=trustpilotFor(name),count=f?.trustpilotReviews==null?null:Number(f.trustpilotReviews);return f&&f.trustpilotRating!=null?`<span class="trustpilot-line">★ ${f.trustpilotRating.toFixed(1)} · ${count==null?'—':count.toLocaleString()} reviews</span>`:''};
