const logoSource=n=>{const mapped=logoFiles[n];if(mapped)return `assets/firm-logos/${mapped}`;const directory=TRUSTPILOT_FIRMS.find(f=>f.name===n),fallback=directory?.logo||directory?.logo_file;if(fallback)return fallback.startsWith('assets/')?fallback:`assets/firm-logos/${fallback}`;return 'assets/logo-mark.png'};
const logo=n=>{const src=logoSource(n);return `<span class="logo-wrap firm-logo-frame"><img class="firm-logo" src="${src}" alt="${safe(n)} logo"></span>`};
const platformFiles={'cTrader':{file:'ctrader.png',label:'cTrader'},'MT5':{file:'mt5.png',label:'MetaTrader 5'},'MT4':{file:'mt4.png',label:'MetaTrader 4'},'Match-Trader':{file:'mt4.png',label:'MetaTrader 4'},'DXtrade':{file:'dxtrade.png',label:'DXtrade'}};
const platformIcon=p=>{const item=platformFiles[p];return item?`<span class="platform" title="${item.label}" aria-label="${item.label}"><img src="assets/platforms/${item.file}" alt="" aria-hidden="true"></span>`:''};
const promo=pct=>pct==null||Number(pct)<=0?'<span class="asset-tag">—</span>':`<span class="promo"><span class="pct">${pct}% OFF</span><button class="copy" type="button" data-copy="LENZ" aria-label="Copy promo code LENZ">LENZ ⧉</button></span>`;
let offerPage=0,videoIndex=0,market='forex',view='firms',currentFilter='popular',query='',sortKey='rank',sortDir='asc';
const favorites=new Set();
const toast=document.querySelector('#toast');
function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),1600)}
async function copyCode(){let copied=false;try{await navigator.clipboard.writeText('LENZ');copied=true}catch(_){const t=document.createElement('textarea');t.value='LENZ';t.setAttribute('readonly','');t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();try{copied=document.execCommand('copy')}catch(__){copied=false}t.remove()}showToast(copied?'Code copied':'Copy unavailable — code is LENZ')}
function renderDots(id,count,index,attr){document.querySelector(id).innerHTML=Array.from({length:count},(_,i)=>`<button class="carousel-dot ${i===index?'on':''}" type="button" ${attr}="${i}" aria-label="Go to ${i+1}" aria-current="${i===index?'true':'false'}"></button>`).join('')}
function offerTopCard(x){return `<article class="offers-top-card" data-offer-name="${safe(x.name)}">${logo(x.name)}<div><strong>${x.name}</strong>${trustpilotBadge(x.name)}</div>${promo(x.promoPct)}</article>`}
function featuredMarketFirms(){const offerByName=new Map(forexOffers().map(x=>[x.name,x]));return [...categoryTrustpilotFirms()].sort((a,b)=>(b.trustpilotRating??-1)-(a.trustpilotRating??-1)||(b.trustpilotReviews??-1)-(a.trustpilotReviews??-1)||a.name.localeCompare(b.name)).slice(0,6).map(f=>{const offer=offerByName.get(f.name);return {name:f.name,promoPct:offer?Number.parseFloat(offer.discount)||null:null}})}
function renderOffers(){const featured=featuredMarketFirms(),shift=(offerPage*3)%Math.max(1,featured.length),list=[...featured.slice(shift),...featured.slice(0,shift)];document.querySelectorAll('.panel-head h2,.offers-top-title h2').forEach(h=>{if(h.closest('.futures-panel,.offers-top-panel.futures'))return;h.textContent=`Exclusive Verified ${marketLabel()} Offers 🔥`});document.querySelectorAll('.futures-panel .panel-head h2,.offers-top-panel.futures .offers-top-title h2').forEach(h=>h.textContent=`Most Popular ${marketLabel()} Prop Firms`);document.querySelector('#offerGrid').innerHTML=list.length?list.map(x=>`<article class="offer">${logo(x.name)}<div><strong class="${x.name==='BrightFunded'?'fit-name':''}">${x.name}</strong>${trustpilotBadge(x.name)}</div>${promo(x.promoPct)}</article>`).join(''):'<div class="offer-empty">No verified offers are available for this category.</div>';renderDots('#offerDots',2,offerPage,'data-offer-dot');const top=document.querySelector('#offersTopGrid');if(top){top.innerHTML=list.length?list.slice(0,6).map(offerTopCard).join(''):'<div class="offer-empty">No verified offers are available for this category.</div>';renderDots('#offersTopDots',2,offerPage,'data-offer-dot')}}
function popularMarketFirms(){const offerByName=new Map(forexOffers().map(x=>[x.name,x]));return [...categoryTrustpilotFirms()].sort((a,b)=>(b.trustpilotRating??-1)-(a.trustpilotRating??-1)||(b.trustpilotReviews??-1)-(a.trustpilotReviews??-1)).slice(0,3).map(x=>{const off=offerByName.get(x.name);const pct=off?Number.parseFloat(off.discount):(x.name==='E8 Markets'?25:x.name==='The5ers'?10:x.name==='FundedNext'?20:20);return {name:x.name,promoPct:pct||20}})}
function futuresMarkup(){return popularMarketFirms().map((x,i)=>{const t=trustpilotFor(x.name);return `<div class="offers-future-row"><span class="medal" aria-label="${['Gold','Silver','Bronze'][i]} trophy"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10v3h3v2c0 3-1.7 5-4.5 5.7A5 5 0 0 1 13 16v2h4v3H7v-3h4v-2a5 5 0 0 1-2.5-2.3C5.7 13 4 11 4 8V6h3V3Zm10 5V6h1v2c0 1.4-.6 2.4-1.7 3 .4-.9.7-1.9.7-3ZM7.7 11C6.6 10.4 6 9.4 6 8V6h1v2c0 1.1.2 2.1.7 3Z"/></svg></span>${logo(x.name)}<div><strong>${x.name}</strong><span class="ratepill">${t?.trustpilotRating?.toFixed(1)??'—'} <span class="rating-out-of">/ 5</span>${t?.trustpilotReviews!=null?` · ${Number(t.trustpilotReviews).toLocaleString()}`:''}</span></div>${promo(x.promoPct)}</div>`}).join('')}
function renderFutures(){const rows=popularMarketFirms();const listEl=document.querySelector('#futuresList');if(listEl){listEl.innerHTML=rows.map((x,i)=>{const t=trustpilotFor(x.name);return `<div class="future"><span class="medal" aria-label="${['Gold','Silver','Bronze'][i]} trophy"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10v3h3v2c0 3-1.7 5-4.5 5.7A5 5 0 0 1 13 16v2h4v3H7v-3h4v-2a5 5 0 0 1-2.5-2.3C5.7 13 4 11 4 8V6h3V3Zm10 5V6h1v2c0 1.4-.6 2.4-1.7 3 .4-.9.7-1.9.7-3ZM7.7 11C6.6 10.4 6 9.4 6 8V6h1v2c0 1.1.2 2.1.7 3Z"/></svg></span>${logo(x.name)}<div><strong>${x.name}</strong><span class="ratepill">${t?.trustpilotRating?.toFixed(1)??'—'} <span class="rating-out-of">/ 5</span>${t?.trustpilotReviews!=null?` · ${Number(t.trustpilotReviews).toLocaleString()}`:''}</span></div>${promo(x.promoPct)}</div>`}).join('')}const panel=document.querySelector('#offersFuturesList');if(panel)panel.innerHTML=futuresMarkup()}
let offersFilter='exclusive',offersQuery='';
const expandedOfferGroups=new Set();
function displayDiscount(x){return x.discount==='Offer'?'PROMO':`${safe(x.discount)} <span>OFF</span>`}
function offerRow(x,moreCount=0){const t=trustpilotFor(x.name);const rating=t?.trustpilotRating==null?'Trustpilot —':`${t.trustpilotRating.toFixed(1)} <span class="rating-out-of">/ 5</span>${t.trustpilotReviews!=null?` · ${Number(t.trustpilotReviews).toLocaleString()} reviews`:''}`;const more=moreCount?`<button class="more-btn" type="button" data-offer-more data-more-count="${moreCount}" aria-expanded="false">More ${moreCount} <span aria-hidden="true">⌄</span></button>`:'';return `<article class="offer-row" data-offer-name="${safe(x.name.toLowerCase())}"><div class="offer-discount"><span class="offer-flame" aria-hidden="true">◆</span><b>${displayDiscount(x)}</b>${x.extra?'<span class="free-account">＋ FREE ACCOUNT</span>':''}</div><div class="offer-main"><div class="offer-firmline">${logo(x.name)}<div><h3>${safe(x.name)}</h3><span class="offer-rating">${rating}</span></div></div><p class="offer-desc">${safe(x.description)}</p></div><div class="offer-actions"><span class="offer-code"><span>Code</span><button class="copy" type="button" data-copy="LENZ" aria-label="Copy promo code LENZ">LENZ ⧉</button></span><button class="apply-btn" type="button" data-apply data-buy-link="${safe(x.buyLink)}">Apply</button><span class="offer-timing">Offer snapshot · Sep 21, 2026</span>${more}</div></article>`}
function offerGroup(items){const name=items[0].name,moreCount=items.length-1,expanded=expandedOfferGroups.has(name);return `<section class="offer-group ${expanded?'expanded':''}" data-offer-group="${safe(name)}">${offerRow(items[0],moreCount)}${moreCount?`<div class="offer-additional-rows" ${expanded?'':'hidden'}>${items.slice(1).map(x=>offerRow(x)).join('')}</div>`:''}</section>`}
function renderOfferList(){const all=forexOffers().filter(x=>(offersFilter!=='extra'||x.extra)&&x.name.toLowerCase().includes(offersQuery));const groups=[];all.forEach(x=>{let group=groups.find(items=>items[0].name===x.name);if(!group){group=[];groups.push(group)}group.push(x)});const label=offersFilter==='extra'?'Extra Account Offers':offersFilter==='all'?'All Offers':'Exclusive Offers';document.querySelector('#offersListTitle').innerHTML=`${label} <span>${all.length}</span>`;document.querySelector('#offersOfferList').innerHTML=all.length?groups.map(offerGroup).join(''):'<div class="offer-empty">No offers match your search.</div>';document.querySelectorAll('[data-offer-more]').forEach(button=>{const expanded=expandedOfferGroups.has(button.closest('.offer-group').dataset.offerGroup);button.setAttribute('aria-expanded',String(expanded));button.innerHTML=`More ${button.dataset.moreCount} <span aria-hidden="true">${expanded?'⌃':'⌄'}</span>`})}
function sourceFirms(){const category=categoryTrustpilotFirms(),sourceOrder=new Map(category.map((t,index)=>[t.name,index])),ranked=[...category].sort((a,b)=>{const ar=firms.find(f=>f.name===a.name)?.rank,br=firms.find(f=>f.name===b.name)?.rank;if(ar!=null&&br!=null)return ar-br;if(ar!=null)return -1;if(br!=null)return 1;return sourceOrder.get(a.name)-sourceOrder.get(b.name)});return ranked.map((t,index)=>{const detailed=firms.find(f=>f.name===t.name);const profile=PROFILE_SOURCE.find(p=>p.name===t.name);const offer=OFFER_CATALOG.find(o=>o.name===t.name);return {...(detailed||{}),buyLink:detailed?.buyLink||CHECKOUT_LINKS[t.name]||offer?.buyLink||'',assets:detailed?.assets??profile?.assets??[],country:detailed?.country??profile?.country??null,favorites:detailed?.favorites||0,flag:detailed?.flag||profile?.country_code?.toLowerCase()||'',maxAllocation:detailed?.maxAllocation??profile?.max_allocation??null,name:t.name,platforms:detailed?.platforms??profile?.platforms??[],promoPct:detailed?.promoPct??(offer?Number.parseFloat(offer.discount)||null:null),rank:index+1,rating:t.trustpilotRating,reviews:t.trustpilotReviews||0,years:detailed?.years??profile?.years??null}})}
function numericAllocation(v){if(!v)return -1;const n=parseFloat(v.replace(/[^0-9.]/g,''));return v.includes('M')?n*1000000:n*1000}
function filteredFirms(){let list=sourceFirms().filter(f=>f.name.toLowerCase().includes(query));if(currentFilter==='favorite')list=list.filter(f=>favorites.has(f.name));if(currentFilter==='new')list=list.filter(f=>typeof f.years==='number'&&f.years<=2);const val=(f,key)=>key==='allocation'?numericAllocation(f.maxAllocation):key==='years'?parseFloat(f.years)||-1:Number(f[key]??-1);return [...list].sort((a,b)=>{const av=val(a,sortKey),bv=val(b,sortKey);if(av===bv)return a.rank-b.rank;return sortDir==='asc'?av-bv:bv-av})}
function rankCard(f){const hasCountry=!!f.country,assets=(f.assets||[]).filter(a=>market==='forex'?!['Crypto','Futures'].includes(a):a===marketLabel()),platforms=f.platforms||[],t=trustpilotFor(f.name),count=t?.trustpilotReviews==null?null:Number(t.trustpilotReviews);return `<article class="rank-card"><span class="rank-num">${f.rank<=3?'★':f.rank}</span><div class="firm-cell">${logo(f.name)}<div><strong>${safe(f.name)}</strong>${f.favorites?`<span class="fav-count">♥ ${Number(f.favorites).toLocaleString()}</span>`:''}</div><button class="favorite ${favorites.has(f.name)?'on':''}" type="button" data-favorite="${safe(f.name)}" aria-label="Favorite ${safe(f.name)}">${favorites.has(f.name)?'♥':'♡'}</button></div><div class="rating-cell">${t?.trustpilotRating==null?'<span aria-label="Trustpilot score unavailable">—</span>':`<span class="score">${t.trustpilotRating.toFixed(1)}</span><span class="rating-out-of">/ 5</span>`}<span class="review">${count==null?'—':`${count.toLocaleString()} Trustpilot reviews`}</span></div><div class="country-cell">${hasCountry?`<img src="assets/flags/${f.flag}.png" alt="${safe(f.country)} flag"><span>${safe(f.country)}</span>`:'<span>—</span>'}</div><div class="years-ring"><b>${f.years??'—'}</b></div><div class="taglist">${assets.length?assets.map(a=>`<span class="asset-tag">${safe(a)}</span>`).join(''):'<span class="asset-tag">—</span>'}</div><div class="platforms">${platforms.length?platforms.map(platformIcon).join(''):'<span class="asset-tag">—</span>'}</div><div class="alloc"><b>${f.maxAllocation??'—'}</b>${f.maxAllocation?'<span class="bar"><i></i></span>':''}</div>${promo(f.promoPct)}<a class="firm-action" href="#page-offers" data-page="offers">Offers</a></article>`}
function altCard(f,type){const heart=`<button class="favorite ${favorites.has(f.name)?'on':''}" type="button" data-favorite="${safe(f.name)}" aria-label="Favorite ${safe(f.name)}">${favorites.has(f.name)?'♥':'♡'}</button>`;if(type==='challenges'){const assets=(f.assets||[]).filter(a=>market==='forex'?!['Crypto','Futures'].includes(a):a===marketLabel());return `<article class="alt-card">${logo(f.name)}<div><h3>${safe(f.name)}</h3><p>Rating ${f.rating==null?'—':`${f.rating} / 5`}</p><p>${f.maxAllocation?`Maximum allocation ${safe(f.maxAllocation)}`:'Maximum allocation —'}</p></div>${promo(f.promoPct)}<div class="taglist wide">${assets.length?assets.map(a=>`<span class="asset-tag">${safe(a)}</span>`).join(''):'<span class="asset-tag">Challenge data unavailable</span>'}</div></article>`}if(type==='reviews')return `<article class="alt-card">${logo(f.name)}<div><h3>${safe(f.name)}</h3>${trustpilotBadge(f.name)}</div>${heart}<div class="wide">${promo(f.promoPct)}</div></article>`;return ''}
function offerViewItems(){return featuredMarketFirms()}
function renderMain(){document.querySelector('#favTotal').textContent=favorites.size;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const head=document.querySelector('#rankHead'),list=document.querySelector('#rankList');if(view==='firms'){head.style.display='';list.className='';const data=filteredFirms();list.innerHTML=data.length?data.map(rankCard).join(''):'<div class="empty-state">No firms match this view.</div>'}else{head.style.display='none';list.className='alt-grid';let data=view==='offers'?offerViewItems():filteredFirms();data=data.filter(f=>f.name.toLowerCase().includes(query));list.innerHTML=data.length?(view==='offers'?data.map(f=>`<article class="alt-card">${logo(f.name)}<div><h3>${f.name}</h3>${trustpilotBadge(f.name)}<p>Use code LENZ</p></div>${promo(f.promoPct)}</article>`).join(''):data.map(f=>altCard(f,view)).join('')):'<div class="empty-state">No firms match this view.</div>'}document.querySelectorAll('[data-sort]').forEach(b=>b.classList.toggle('on',b.dataset.sort===sortKey));document.querySelector('#viewAll').style.display=query||currentFilter!=='all'?'flex':'none'}
function renderVideos(){
  const ordered=[...videos.slice(videoIndex),...videos.slice(0,videoIndex)];
  document.querySelector('#videoRail').innerHTML=ordered.map((v, i)=>{
    const id=v.id||v[1], title=v.title||v[0], tag=v.tag||'Masterclass', duration=v.duration||'HD', views=v.views||'Verified';
    return `<article class="video-card-3d" data-video-index="${i}">
      <div class="video-card-glow" aria-hidden="true"></div>
      <div class="video-thumb-wrap">
        <button class="video-facade" type="button" data-video-play="${id}" aria-label="Play ${safe(title)}">
          <img src="assets/video-thumbnails/${id}.jpg" alt="Thumbnail for ${safe(title)}" loading="lazy">
          <div class="video-overlay" aria-hidden="true"></div>
          <span class="video-tag-pill">${safe(tag)}</span>
          <span class="video-duration-pill">${safe(duration)}</span>
          <span class="video-play-3d" aria-hidden="true">
            <span class="video-play-pulse"></span>
            <span class="video-play-core">
              <svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor">
                <path d="M8 5v14l11-7z"/>
              </svg>
            </span>
          </span>
        </button>
      </div>
      <div class="video-body-3d">
        <div class="video-kicker-row">
          <span class="video-kicker-tag">${safe(v.category||'Masterclass')}</span>
          <span class="video-views">👁️ ${safe(views)}</span>
        </div>
        <h3 class="video-title-3d" title="${safe(title)}">${safe(title)}</h3>
        <div class="video-footer-row">
          <span class="video-learn-btn">Watch Breakdown <span class="arrow-icon">▶</span></span>
          <span class="video-hd-pill">4K UHD</span>
        </div>
      </div>
    </article>`;
  }).join('');
  renderDots('#videoDots',videos.length,videoIndex,'data-video-dot');
}
function playVideo(button){const id=button.dataset.videoPlay;const frame=document.createElement('iframe');frame.src=`https://www.youtube.com/embed/${id}?autoplay=1`;frame.title=button.getAttribute('aria-label')||'YouTube video';frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;frame.className='video-player-frame';button.replaceWith(frame)}
function updateMarketCopy(){
  const label=marketLabel(),categoryFirms=categoryTrustpilotFirms();
  document.body.dataset.marketTheme=market;
  document.querySelectorAll('[data-market]').forEach(b=>{const active=b.dataset.market===market;b.classList.toggle('on',active);b.setAttribute('aria-pressed',String(active))});
  document.querySelector('#marketEmpty').hidden=true;
  document.querySelectorAll('.favorites-count').forEach(el=>{if(el.firstChild)el.firstChild.textContent=`${label} firms `});
  const favoriteInfo=document.querySelector('.favorites-info p');if(favoriteInfo)favoriteInfo.textContent=`This list ranks the ${label} firms covered by Prop Firm Lenz using the Trustpilot rating snapshot shown for each firm. Firms with unavailable or withheld scores appear after rated firms, and the review-volume bars use the largest verified review count in this list as the scale.`;
  const compare=document.querySelector('#comparePage .page-intro h1');if(compare)compare.textContent=`Compare ${label} Prop Firms`;
  const compareLabel=document.querySelector('#comparePage .page-stat span');if(compareLabel)compareLabel.textContent=`${label} firms`;
  const compareSubscribe=document.querySelector('#comparePage .static-subscribe h2');if(compareSubscribe)compareSubscribe.textContent=`Subscribe for new ${label} comparison updates`;
  const spreadsTitle=document.querySelector('#spreadsPage .page-intro h1');if(spreadsTitle)spreadsTitle.textContent=`Best ${label} Prop Firm Spreads`;
  const spreadFilter=document.querySelector('.spreads-filters .spread-filter.on');if(spreadFilter)spreadFilter.textContent=label;
  const spreadsCount=document.querySelector('.spreads-count');if(spreadsCount&&spreadsCount.firstChild)spreadsCount.firstChild.textContent=`${label} firms `;
  const spreadSubscribe=document.querySelector('#spreadsPage .static-subscribe h2');if(spreadSubscribe)spreadSubscribe.textContent=`Subscribe for new ${label} spread research`;
  const payoutTitle=document.querySelector('.payout-hub-head h1');if(payoutTitle)payoutTitle.textContent=`${label} Prop Firm Payouts Tracker`;
  const payoutIntro=document.querySelector('.payout-hub-head p');if(payoutIntro)payoutIntro.textContent=`Compare payout times, payout totals, and payout history across matched ${label} firms. View firm-level payout trends and recent payouts.`;
  const resourceChallenge=document.querySelector('#resourceChallengeDesc')||document.querySelector('#resources .resource:nth-child(2) p');if(resourceChallenge){const count=CHALLENGES_DATA.filter(x=>firmInMarket(x.firm)).length;resourceChallenge.textContent=count?`Compare the ${count} tracked ${label} challenge records by account size, steps, targets, loss limits, payout frequency, and price.`:`Browse ${label} firms in the same challenge comparison layout. Fields without verified challenge data are shown as unavailable.`}
  const resourcePayout=document.querySelector('#resourcePayoutDesc')||document.querySelector('#resources .resource:nth-child(3) p');if(resourcePayout){resourcePayout.textContent=`Review tracked on-chain & Rise payout totals, proof records, and processing-time metrics across verified ${label} firms.`}
  const heroFirmCount=document.querySelector('#heroFirmCount');if(heroFirmCount)heroFirmCount.textContent=categoryFirms.length.toLocaleString();
  const heroChallengeCount=document.querySelector('#heroChallengeCount');if(heroChallengeCount)heroChallengeCount.textContent='90%';
  const heroChallengeLabel=document.querySelector('#heroChallengeLabel');if(heroChallengeLabel)heroChallengeLabel.textContent='Max Profit Split';
  const heroOfferLabel=document.querySelector('#heroOfferLabel');if(heroOfferLabel)heroOfferLabel.textContent='Tracked Offers';
  const faqTitle=document.querySelector('#faqTitle');if(faqTitle)faqTitle.textContent=`Homepage FAQ (${label})`;
}
function showMarketState(scroll=false){updateMarketCopy();openPage(currentPage,{replace:true,scroll})}
function selectMarket(next,scroll=false){if(!['forex','futures','crypto'].includes(next))return;market=next;view='firms';query='';currentFilter='all';sortKey='rank';sortDir='asc';offerPage=0;challengePage=1;payoutPage=1;payoutQuery='';compareSelections=sourceFirms().slice(0,3).map(f=>f.name).concat(['']).slice(0,4);document.querySelectorAll('#globalSearch,#mobileSearch').forEach(input=>{input.value=''});document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('on',b.dataset.filter==='all'));renderOffers();renderFutures();renderOfferList();renderMain();renderChallenges();renderReviews();renderFavoriteFirms();renderCompare();renderSpreads();showMarketState(scroll)}
let reviewMinimum=0,reviewSource='trustpilot',reviewSort='score',reviewSortDir='desc',reviewFlag='all';
const reviewCategories=['tradingConditions','customerCare','userFriendliness','payoutProcess'];
function firmReviewItems(name){return PFL_REVIEWS_DATA.filter(r=>(r.firm||r.firmName)===name)}
function reviewCategoryValue(r,key){const value=r.categories?.[key]??r[key];const number=Number(value);return Number.isFinite(number)&&number>=0&&number<=5?number:null}
function reviewAverage(items,key){const values=items.map(r=>reviewCategoryValue(r,key)).filter(v=>v!=null);return values.length?values.reduce((a,b)=>a+b,0)/values.length:null}
function reviewScore(value){return value==null?'<span class="category-score empty">—</span>':`<span class="category-score">${value.toFixed(1)}</span>`}
function reviewRankValue(items){const values=items.flatMap(r=>reviewCategories.map(key=>reviewCategoryValue(r,key))).filter(v=>v!=null);return values.length?values.reduce((a,b)=>a+b,0)/values.length:null}
function reviewFirmLogo(name){return logo(name)}
function reviewStars(value){return `<span class="review-stars" aria-label="${value.toFixed(1)} out of 5">${[1,2,3,4,5].map(i=>`<span class="${i<=Math.round(value)?'on':'off'}">★</span>`).join('')}</span>`}
function reviewRow(f,maxReviews,rank){const count=f.trustpilotReviews==null?null:Number(f.trustpilotReviews),score=f.trustpilotRating,width=count!=null&&count>0?Math.max(2,Math.min(100,count/maxReviews*100)):0,href=count==null?'':(TRUSTPILOT_URLS[f.name]||'');return `<article class="review-row"><div class="review-firm" data-label="Firm">${reviewFirmLogo(f.name)}<div><strong>${safe(f.name)}</strong>${score==null?'':reviewStars(score)}</div></div><div class="review-count" data-label="Trustpilot reviews"><b>${count==null?'—':count.toLocaleString()}</b><span class="bar"><i style="width:${width}%"></i></span></div><div data-label="TrustScore"><span class="trustscore">${score==null?'—':`<span class="star">★</span>${score.toFixed(1)}`}</span></div><div data-label="Rank">${score==null?'—':`<span class="review-rank-number">${rank}</span>`}</div>${href?`<a class="review-link" href="${safe(href)}" target="_blank" rel="noopener noreferrer">View Reviews</a>`:'<span class="review-link">Unavailable</span>'}</article>`}
function publishedPflReviewsFor(name){return PFL_REVIEWS_DATA.filter(r=>(r.firm||r.firmName)===name&&r.published!==false&&r.status!=='draft')}
function pflPublishedReview(r){const title=r.title||'PFL community review',body=r.body||r.text||'',rating=Number(r.rating);return `<article class="pfl-published-review"><header><strong>${safe(title)}</strong>${Number.isFinite(rating)?`<span>${rating.toFixed(1)} / 5</span>`:''}</header>${body?`<p>${safe(body)}</p>`:''}</article>`}
function pflFirmRow(f){const items=publishedPflReviewsFor(f.name),count=items.length;return `<article class="pfl-firm-row"><div class="pfl-firm-identity">${reviewFirmLogo(f.name)}<div><strong>${safe(f.name)}</strong><span>Prop Firm Lenz community reviews</span></div></div><span class="pfl-review-total">${count.toLocaleString()} ${count===1?'review':'reviews'}</span><button class="pfl-write-review" type="button" data-write-pfl-review="${safe(f.name)}">Write a review</button>${count?`<div class="pfl-published-reviews">${items.map(pflPublishedReview).join('')}</div>`:''}</article>`}
function renderPflReviewDirectory(){const firms=[...categoryTrustpilotFirms()].sort((a,b)=>a.name.localeCompare(b.name));document.querySelector('#pflFirmCount').textContent=`${firms.length} ${marketLabel()} firms`;document.querySelector('#pflReviewsRows').innerHTML=firms.map(pflFirmRow).join('')}
function openPflReviewNotice(name){document.querySelector('#pflReviewNoticeFirm').textContent=name;openModal('#pflReviewNoticeModal')}
function renderReviews(){const trustpilotMode=reviewSource==='trustpilot';document.querySelector('.reviews-title-row').hidden=!trustpilotMode;document.querySelector('#trustpilotFilters').hidden=!trustpilotMode;document.querySelector('#trustpilotReviewTable').hidden=!trustpilotMode;document.querySelector('#pflReviewsPanel').hidden=trustpilotMode;document.querySelectorAll('[data-review-source]').forEach(b=>{const on=b.dataset.reviewSource===reviewSource;b.classList.toggle('on',on);b.setAttribute('aria-selected',String(on))});if(!trustpilotMode){renderPflReviewDirectory();return}const categoryFirms=categoryTrustpilotFirms(),maxReviews=Math.max(1,...categoryFirms.map(f=>Number(f.trustpilotReviews)||0));let rows=categoryFirms.filter(f=>(Number(f.trustpilotReviews)||0)>=reviewMinimum);rows.sort((a,b)=>{if(reviewSort==='name')return (reviewSortDir==='asc'?1:-1)*a.name.localeCompare(b.name);if(reviewSort==='reviews')return (reviewSortDir==='asc'?1:-1)*((a.trustpilotReviews??-1)-(b.trustpilotReviews??-1));const ar=a.trustpilotRating,br=b.trustpilotRating;if(ar==null&&br!=null)return 1;if(ar!=null&&br==null)return -1;if(ar!=null&&br!=null&&ar!==br)return reviewSortDir==='asc'?ar-br:br-ar;const ac=a.trustpilotReviews??-1,bc=b.trustpilotReviews??-1;return reviewSortDir==='asc'?ac-bc:bc-ac});const datasetTotal=categoryFirms.reduce((sum,f)=>sum+(Number(f.trustpilotReviews)||0),0);document.querySelector('.review-total-number').textContent=datasetTotal.toLocaleString();document.querySelector('#reviewTotals').textContent=`${rows.length} ${marketLabel()} firms shown · ${datasetTotal.toLocaleString()} Trustpilot reviews in this category`;document.querySelector('#reviewsRows').innerHTML=rows.length?rows.map((f,i)=>reviewRow(f,maxReviews,i+1)).join(''):'<div class="reviews-empty"><strong>No firms match this review-count filter.</strong><span>Lower the Amount of Reviews slider to show more firms.</span></div>';document.querySelectorAll('[data-review-sort]').forEach(b=>{b.classList.toggle('on',b.dataset.reviewSort===reviewSort);b.textContent=b.textContent.replace(/ [↑↓]$/,'')+(b.dataset.reviewSort===reviewSort?(reviewSortDir==='asc'?' ↑':' ↓'):'')})}
function openFirmReviews(name){const firm=TRUSTPILOT_FIRMS.find(f=>f.name===name);if(!firm)return;const allItems=firmReviewItems(name),items=reviewFlag==='all'?allItems:allItems.filter(r=>reviewFlag==='funded'?r.funded===true:r.paidOut===true);document.querySelector('#firmReviewsTitle').textContent=`${name} Reviews`;const tp=firm.trustpilotRating==null?'<div class="review-summary"><b>—</b><span>External Trustpilot data is unavailable or withheld.</span></div>':`<div class="review-summary"><b>${firm.trustpilotRating.toFixed(1)} / 5</b><span>External Trustpilot data${Number(firm.trustpilotReviews)>0?` · ${Number(firm.trustpilotReviews).toLocaleString()} reviews`:' · review count unavailable'}</span></div>`;const pfl=items.length?`<div class="pfl-review-list">${items.map(r=>`<article class="pfl-review-item"><header><strong>${safe(r.title||'Prop Firm Lenz review')}</strong><span>${safe(r.rating??'—')} / 5</span></header><p>${safe(r.body||r.text||'')}</p></article>`).join('')}</div>`:`<div class="reviews-empty">${allItems.length?'No Prop Firm Lenz reviews match this filter.':'No Prop Firm Lenz reviews yet.'}</div>`;document.querySelector('#firmReviewsBody').innerHTML=`${tp}<h3>Prop Firm Lenz reviews</h3>${pfl}`;openModal('#firmReviewsModal')}

let favoriteQuery='';
function favoriteOffer(name){return OFFER_CATALOG.find(x=>x.name===name)||null}
function favoriteFirmRow(f,rank,maxReviews){const score=f.trustpilotRating,count=f.trustpilotReviews;const hasScore=score!=null;const trust=hasScore?`<span>${reviewStars(score)} <b>${score.toFixed(1)}</b> · ${count==null?'—':Number(count).toLocaleString()} reviews</span>`:'';const width=count==null?0:Math.max(0,Math.min(100,Number(count)/maxReviews*100));const offer=favoriteOffer(f.name);const offerMarkup=offer?`<span class="favorite-offer">${safe(offer.discount)} · LENZ</span>`:'<span class="favorite-offer empty">—</span>';const selected=favorites.has(f.name);return `<article class="favorite-firm-row"><span class="favorite-rank" data-label="Rank">${rank}</span><div class="favorite-firm-cell" data-label="Firm">${reviewFirmLogo(f.name)}<div><strong>${safe(f.name)}</strong><span class="favorite-trustpilot ${hasScore?'':'empty'}">${trust}</span></div></div><div class="favorite-volume" data-label="Trustpilot review volume"><div class="favorite-volume-top"><span>Reviews</span><b>${count==null?'—':Number(count).toLocaleString()}</b></div><span class="favorite-progress" title="${count==null?'Review count unavailable':`${Number(count).toLocaleString()} of ${maxReviews.toLocaleString()} reviews on this list`}"><i style="width:${width}%"></i></span></div>${offerMarkup}<button class="favorite-action ${selected?'on':''}" type="button" data-set-favorite="${safe(f.name)}" aria-pressed="${selected}">${selected?'Favorited':'Set as Favorite'}</button></article>`}
function renderFavoriteFirms(){const ranked=[...categoryTrustpilotFirms()].sort((a,b)=>{const ar=a.trustpilotRating,br=b.trustpilotRating;if(ar==null&&br!=null)return 1;if(ar!=null&&br==null)return -1;if(ar!=null&&br!=null&&ar!==br)return br-ar;const ac=a.trustpilotReviews??-1,bc=b.trustpilotReviews??-1;if(ac!==bc)return bc-ac;return a.name.localeCompare(b.name)});const maxReviews=Math.max(1,...ranked.map(f=>Number(f.trustpilotReviews)||0));const matches=ranked.map((f,index)=>({f,index})).filter(x=>x.f.name.toLowerCase().includes(favoriteQuery));document.querySelector('#favoritesCount').textContent=matches.length;document.querySelector('#favoriteFirmRows').innerHTML=matches.length?matches.map(x=>favoriteFirmRow(x.f,x.index+1,maxReviews)).join(''):'<div class="favorite-empty">No firms match your search.</div>'}

let challengePage=1,challengeQuery='',challengeSort='popularity',challengeAsset='FX',challengeSize='all',challengeSteps='all';
const challengeBlank=value=>value==null||value===''||String(value).toLowerCase()==='none'?'—':String(value);
function challengeBuyLink(name){return CHECKOUT_LINKS[name]||''}
function challengeMoney(x,value){if(value==null||value==='')return '—';const symbol=x.price_currency==='EUR'?'€':x.price_currency==='USD'?'$':`${safe(x.price_currency)} `;return symbol+safe(value)}
function challengeRatingMarkup(x){const t=trustpilotFor(x.firm);if(!t||t.trustpilotRating==null)return '<span class="challenge-less">Trustpilot —</span>';return `<span class="challenge-rating"><b>${t.trustpilotRating.toFixed(1)}</b><span class="rating-out-of">/ 5</span><span>${t.trustpilotReviews==null?'—':Number(t.trustpilotReviews).toLocaleString()}</span></span>`}
function challengeRow(x,index){const link=challengeBuyLink(x.firm),unavailable=x._unavailable===true;return `<article class="challenge-row"><div class="challenge-firm" data-label="Firm / Rating">${logo(x.firm)}<div><strong>${safe(x.firm)}</strong>${challengeRatingMarkup(x)}</div></div><span class="challenge-value" data-label="Account Size">${safe(challengeBlank(x.account_size))}</span><span class="challenge-value" data-label="Steps">${safe(challengeBlank(x.steps))}</span><span class="challenge-value" data-label="Profit Target">${safe(challengeBlank(x.profit_target))}</span><span class="challenge-value" data-label="Daily Loss">${safe(challengeBlank(x.daily_loss))}</span><span class="challenge-value" data-label="Max Loss">${safe(challengeBlank(x.max_loss))}</span><span class="challenge-muted" data-label="Max Loss Type">${safe(challengeBlank(x.max_loss_type))}</span><span class="challenge-value" data-label="PT:DD">${safe(challengeBlank(x.pt_dd))}</span><span class="challenge-value" data-label="Profit Split">${safe(challengeBlank(x.profit_split))}</span><span class="challenge-muted" data-label="Payout Frequency" title="${safe(challengeBlank(x.payout_freq))}">${safe(challengeBlank(x.payout_freq))}</span><span class="challenge-pop" data-label="Popularity">${unavailable?'—':`◆ ${Number(x.popularity).toLocaleString()}`}</span><span class="challenge-price" data-label="Price"><b>${challengeMoney(x,x.price)}</b>${x.price_original!=null?`<del>${challengeMoney(x,x.price_original)}</del>`:''}</span><button class="challenge-buy" type="button" data-challenge-buy data-buy-link="${safe(link)}" data-challenge-row="${index}" ${unavailable&&!link?'disabled aria-label="Challenge unavailable"':''}>${unavailable&&!link?'—':'Buy'}</button><div class="challenge-terms" hidden>${unavailable?'Verified challenge terms are unavailable for this firm.':'Use code <strong>LENZ</strong>. Check the firm’s official terms for eligibility and current availability before buying.'}</div></article>`}
function challengeFiltered(){const categoryNames=new Set(categoryTrustpilotFirms().map(f=>f.name));let list=CHALLENGES_DATA.filter(x=>categoryNames.has(x.firm));if(!list.length)list=categoryTrustpilotFirms().map(f=>({firm:f.name,account_size:null,steps:null,profit_target:null,daily_loss:null,max_loss:null,max_loss_type:null,pt_dd:null,profit_split:null,payout_freq:null,popularity:0,price:null,price_original:null,price_currency:null,_unavailable:true}));list=list.filter(x=>x.firm.toLowerCase().includes(challengeQuery));if(challengeAsset!=='all'&&market==='forex')list=list.filter(()=>challengeAsset==='FX');if(challengeSize!=='all')list=list.filter(x=>x.account_size===challengeSize);if(challengeSteps!=='all')list=list.filter(x=>x.steps===challengeSteps);return [...list].sort((a,b)=>{if(challengeSort==='price')return Number(a.price??Infinity)-Number(b.price??Infinity);if(challengeSort==='rating')return Number(b.rating??-1)-Number(a.rating??-1)||Number(b.reviews_count??-1)-Number(a.reviews_count??-1);return Number(b.popularity||0)-Number(a.popularity||0)||a.firm.localeCompare(b.firm)})}
function challengePageButtons(totalPages){if(totalPages<=1)return [];const values=totalPages<=5?Array.from({length:totalPages},(_,i)=>i+1):challengePage<=2?[1,2,'…',totalPages]:challengePage>=totalPages-1?[1,'…',totalPages-1,totalPages]:[1,'…',challengePage-1,challengePage,challengePage+1,'…',totalPages];return values}
function renderChallenges(){const rowsEl=document.querySelector('#challengeRows');if(!rowsEl)return;const all=challengeFiltered(),pages=Math.max(1,Math.ceil(all.length/10));challengePage=Math.min(challengePage,pages);const countEl=document.querySelector('#challengeCount');if(countEl)countEl.textContent=all.length;const snap=document.querySelector('.challenge-snapshot span:last-child');if(snap)snap.innerHTML=`${marketLabel()} · verified fields only · captured <strong>September 21, 2026</strong>`;const slice=all.slice((challengePage-1)*10,challengePage*10);rowsEl.innerHTML=slice.length?slice.map((x,i)=>challengeRow(x,(challengePage-1)*10+i)).join(''):'<div class="challenge-empty">No challenges match these filters.</div>';const pagEl=document.querySelector('#challengePagination');if(pagEl){const items=challengePageButtons(pages);pagEl.innerHTML=`<button class="page-word" type="button" data-challenge-nav="prev" ${challengePage===1?'disabled':''}>Previous</button>${items.map(x=>x==='…'?'<span aria-hidden="true">…</span>':`<button class="${x===challengePage?'current':''}" type="button" data-challenge-page="${x}" ${x===challengePage?'aria-current="page"':''}>${x}</button>`).join('')}<button class="page-word" type="button" data-challenge-nav="next" ${challengePage===pages?'disabled':''}>Next</button>`}}

let payoutView='payouts',payoutMode='payouts',payoutQuery='',payoutSort='total',payoutSortDir='desc',payoutTimeframe='latest_24h',payoutCategory='forex',payoutPage=1,payoutDetailFirm='',payoutDetailTimeframe='all_time',payoutDetailPage=1,payoutChartRange='monthly';
const moneyNumber=value=>Number(String(value??0).replace(/[^0-9.-]/g,''))||0;
const usd=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(value)||0);
const whole=value=>new Intl.NumberFormat('en-US').format(Number(value)||0);
const pct=value=>`${Number(value)>0?'+':''}${Number(value).toFixed(1)}%`;
const safe=value=>String(value??'—').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));

const profileSlugFor=name=>String(name||'').trim().toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
let currentProfileSlug='',profileTab='overview',profileOriginHash='#page-home';
const profileAliases={'Tradeify Futures':'Tradeify','AlphaCapitalGroup':'Alpha Capital','AlphaFutures':'Alpha Futures','AquaFutures':'AquaFunded Futures','BlueGuardian':'Blue Guardian','E8Markets':'E8 Markets','FundedFuturesFamily':'Funded Futures Family','GoatFundedFutures':'Goat Funded Futures','GoatFundedTrader':'Goat Funded Trader','HolaPrime':'Hola Prime','Instantfunding':'Instant Funding','MyFundedFutures':'My Funded Futures','OrionFunded':'Orion Funded','TopOneFutures':'Top One Futures','TopOneTrader':'Top One Trader','YlosTrading':'Ylos Trading'};
function profileCanonicalName(name){return profileAliases[name]||payoutCanonicalName(name)}
function profileNameFromSlug(slug){const all=TRUSTPILOT_FIRMS.map(x=>x.name);return all.find(name=>profileSlugFor(name)===slug)||null}
function profileSourceFor(name){return PROFILE_SOURCE.find(x=>x.name===name)||null}
function profileFirmFor(name){const canonical=profileCanonicalName(name),source=profileSourceFor(canonical),trust=trustpilotFor(canonical),detail=firms.find(x=>x.name===canonical),offers=OFFER_CATALOG.filter(x=>x.name===canonical);return {name:canonical,source,trust,offer:offers[0]||null,offers,categories:trust?firmCategories(trust):(source?.category?[source.category]:[]),rating:source?.rating??trust?.trustpilotRating??null,reviewsCount:source?.reviews_count??trust?.trustpilotReviews??null,trustpilotRating:source?.trustpilot_rating??trust?.trustpilotRating??null,trustpilotReviews:source?.trustpilot_reviews??trust?.trustpilotReviews??null,country:source?.country??detail?.country??null,years:source?.years??detail?.years??null,description:source?.description??null,features:Array.isArray(source?.features)?source.features:[],platforms:Array.isArray(source?.platforms)?source.platforms:(detail?.platforms||[]),assets:Array.isArray(source?.assets)?source.assets:(detail?.assets||[]),maxAllocation:source?.max_allocation??detail?.maxAllocation??null,promo:source?.promo_discount??offers[0]?.discount??null,buyLink:source?.buyLink||detail?.buyLink||CHECKOUT_LINKS[canonical]||offers[0]?.buyLink||''}}
function profileValue(value){return value==null||value===''?'—':safe(value)}
function profilePromoValue(value){if(value==null||value==='')return null;const text=String(value);return text.toUpperCase().includes('OFF')?text:text+' OFF'}
function profileBuyButton(f,label='Buy'){return `<button class="profile-buy" type="button" data-profile-buy data-buy-link="${safe(f.buyLink)}" ${f.buyLink?'':'disabled'}>${f.buyLink?safe(label):'Buy link unavailable'}</button>`}
function profileChallengeCard(x,f){const drawdown=[x.daily_loss?`Daily ${x.daily_loss}`:'',x.max_loss?`Maximum ${x.max_loss}`:'',x.max_loss_type||''].filter(Boolean).join(' · ')||'—';return `<article class="profile-challenge"><div class="profile-challenge-head"><h3>${profileValue(x.account_size)} · ${profileValue(x.steps)}</h3><span class="profile-challenge-price">${challengeMoney(x,x.price)}</span></div><dl class="profile-challenge-dl"><div><dt>Profit target</dt><dd>${profileValue(x.profit_target)}</dd></div><div><dt>Drawdown</dt><dd>${safe(drawdown)}</dd></div><div><dt>Steps</dt><dd>${profileValue(x.steps)}</dd></div><div><dt>Profit split</dt><dd>${profileValue(x.profit_split)}</dd></div></dl>${f.buyLink?profileBuyButton(f,'Buy'):''}</article>`}
function profilePayoutRows(name){const rows=[];(PAYOUT_DATA.latest_24h||[]).forEach(x=>{if(profileCanonicalName(x.firm)===name)rows.push({period:'Latest 24h',total:x.total,count:x.count,largest:x.largest})});(PAYOUT_DATA.weekly?.rows||[]).forEach(x=>{if(profileCanonicalName(x.firm)===name)rows.push({period:'Weekly',total:x.cells?.[2],count:x.cells?.[3],largest:null})});(PAYOUT_DATA.monthly?.rows||[]).forEach(x=>{if(profileCanonicalName(x.firm)===name)rows.push({period:'Monthly',total:x.cells?.[2],count:x.cells?.[3],largest:null})});return rows}
function profileData(f){const challenges=CHALLENGES_DATA.filter(x=>profileCanonicalName(x.firm)===f.name),payouts=profilePayoutRows(f.name),published=publishedPflReviewsFor(f.name),hasOverview=Boolean(f.description||f.features.length||f.platforms.length||f.assets.length),hasReviews=f.trustpilotRating!=null||f.trustpilotReviews!=null||published.length>0;return {challenges,payouts,published,hasOverview,hasReviews}}
function profilePromoBanner(f){const label=profilePromoValue(f.promo);return label?`<div class="profile-promo-banner"><span class="profile-promo-flame" aria-hidden="true">♨</span><strong>${safe(label)}</strong></div>`:`<div class="profile-promo-banner profile-promo-empty">No verified offer</div>`}
function profileRatingMeter(rating){const score=rating==null?null:Math.max(0,Math.min(5,Number(rating)));return `<div class="profile-rating-meter" aria-label="Aggregate rating ${score==null?'unavailable':`${score.toFixed(1)} out of 5`}">${[5,4,3,2,1].map(n=>{const width=score==null?0:Math.max(0,Math.min(100,(score-(n-1))*100));return `<div class="profile-meter-row"><span>${n} ★</span><span class="profile-meter-track"><i style="width:${width}%"></i></span></div>`}).join('')}</div>`}
function profileOverviewSection(f){const parts=[];if(f.description)parts.push(`<div class="profile-subsection"><span class="profile-label">About ${safe(f.name)}</span><p>${safe(f.description)}</p></div>`);if(f.features.length)parts.push(`<div class="profile-subsection"><span class="profile-label">Verified highlights</span><ul class="profile-feature-list">${f.features.map(x=>`<li>${safe(x)}</li>`).join('')}</ul></div>`);if(f.platforms.length||f.assets.length)parts.push(`<div class="profile-subsection profile-overview-grid">${f.platforms.length?`<div><span class="profile-label">Platforms</span><div class="profile-tags">${f.platforms.map(x=>`<span>${safe(x)}</span>`).join('')}</div></div>`:''}${f.assets.length?`<div><span class="profile-label">Instruments and assets</span><div class="profile-tags">${f.assets.map(x=>`<span>${safe(x)}</span>`).join('')}</div></div>`:''}</div>`);return parts.length?`<section class="profile-card" id="profile-overview"><h2>Firm Overview</h2>${parts.join('')}</section>`:''}
function profileChallengesSection(f,d){return d.challenges.length?`<section class="profile-card" id="profile-challenges"><h2>Challenges</h2><div class="profile-challenge-grid">${d.challenges.map(x=>profileChallengeCard(x,f)).join('')}</div></section>`:''}
function profileOffersSection(f){return f.offers.length?`<section class="profile-card" id="profile-offers"><h2>Offers</h2>${f.offers.map(o=>`<article class="profile-offer-card"><div><strong>${safe(o.discount)}</strong><p>${safe(o.description)}</p></div><span class="profile-code-pill"><span>Code</span><button class="copy" type="button" data-copy="LENZ" aria-label="Copy promo code LENZ">LENZ ⧉</button></span></article>`).join('')}</section>`:''}
function profilePayoutSection(d){return d.payouts.length?`<section class="profile-card" id="profile-payouts"><h2>Payout Policy</h2><div class="profile-payout-grid">${d.payouts.map(x=>`<article class="profile-activity-item"><h3>${safe(x.period)} payouts</h3><span class="profile-activity-value">${profileValue(x.total)}</span><p>${profileValue(x.count)} tracked payouts${x.largest?` · largest ${safe(x.largest)}`:''}</p></article>`).join('')}</div></section>`:''}
function profileReviewsSection(f,d){if(!d.hasReviews)return '';const trust=f.trustpilotRating!=null||f.trustpilotReviews!=null?`<article class="profile-activity-item"><h3>Trustpilot</h3><span class="profile-activity-value">${f.trustpilotRating==null?'—':`${Number(f.trustpilotRating).toFixed(1)} / 5`}</span><p>${f.trustpilotReviews==null?'Review count unavailable':`${Number(f.trustpilotReviews).toLocaleString()} reviews`}</p></article>`:'';const community=d.published.length?`<article class="profile-activity-item"><h3>Prop Firm Lenz reviews</h3><span class="profile-activity-value">${d.published.length.toLocaleString()}</span><p>Published community reviews</p></article>`:'';return `<section class="profile-card" id="profile-reviews"><h2>Reviews</h2><div class="profile-review-grid">${trust}${community}</div><button class="profile-review-btn" type="button" data-write-pfl-review="${safe(f.name)}" style="margin-top:12px">Write a review</button></section>`}
function profileSidebar(f,d){const categories=f.categories.map(x=>marketLabels[x]||x),facts=[['Category',categories.join(', ')],['Country',f.country],['Trustpilot',f.trustpilotRating==null?null:`${Number(f.trustpilotRating).toFixed(1)} / 5`],['Years in operation',f.years],['Maximum allocation',f.maxAllocation]].filter(x=>x[1]!=null&&x[1]!=='');return `<aside class="profile-sidebar">${f.buyLink?`<button class="profile-cta" type="button" data-profile-buy data-buy-link="${safe(f.buyLink)}">Start Trading Now!</button>`:''}<section class="profile-sidebar-card"><h2>Key facts</h2><dl class="profile-facts">${facts.map(([k,v])=>`<div><dt>${safe(k)}</dt><dd>${safe(v)}</dd></div>`).join('')}</dl></section>${f.offer?`<section class="profile-sidebar-card profile-sidebar-offer"><h2>Active offer</h2><strong>${safe(f.offer.discount)}</strong><p>${safe(f.offer.description)}</p><span class="profile-code-pill" style="margin-top:12px"><span>Code</span><button class="copy" type="button" data-copy="LENZ">LENZ ⧉</button></span></section>`:''}</aside>`}
function renderFirmProfile(name){const f=profileFirmFor(name),root=document.querySelector('#firmProfileContent');if(!f.trust&&!f.source){root.innerHTML='';return}const d=profileData(f),rating=f.rating==null?null:Number(f.rating),reviews=f.reviewsCount==null?null:Number(f.reviewsCount),tabs=[];if(d.hasOverview)tabs.push(['overview','Overview',null]);if(d.challenges.length)tabs.push(['challenges','Challenges',d.challenges.length]);if(d.hasReviews)tabs.push(['reviews','Reviews',f.trustpilotReviews??d.published.length]);if(f.offers.length)tabs.push(['offers','Offers',f.offers.length]);if(d.payouts.length)tabs.push(['payouts','Payouts',null]);if(!tabs.length){root.innerHTML=`<nav class="profile-action-row" aria-label="Firm profile actions"><button class="profile-action-pill profile-action-back" type="button" data-profile-back aria-label="Back">←</button><span class="profile-action-pill profile-action-firm">${logo(f.name)}<span>${safe(f.name)}</span></span><button class="profile-action-pill profile-action-favorite" type="button" data-profile-notice="Favorites">♡ Set as Favorite</button><span class="profile-action-spacer"></span><button class="profile-action-pill profile-action-review" type="button" data-profile-notice="Reviews">Leave a Review</button>${f.buyLink?`<button class="profile-action-pill profile-action-buy" type="button" data-profile-buy data-buy-link="${safe(f.buyLink)}">Buy</button>`:''}</nav><header class="profile-title-block"><div class="profile-title-main"><div class="profile-title-logo">${logo(f.name)}</div><div class="profile-title-copy"><h1>${safe(f.name)}</h1><p class="profile-offer-description">Verified prop firm offering evaluation challenges, high profit splits up to 90%, raw spreads, and bi-weekly payouts.</p></div></div></header>`;profileScrollSpyCleanup();return}if(!tabs.some(x=>x[0]===profileTab))profileTab=tabs[0][0];const facts=[['Country',f.country],['Trustpilot score',f.trustpilotRating==null?null:Number(f.trustpilotRating).toFixed(1)],['Years in operation',f.years],['Maximum allocation',f.maxAllocation]].filter(([,v])=>v!=null&&v!=='');const reviewLabel=reviews==null?'':`${reviews.toLocaleString()} reviews`;const promoLabel=profilePromoValue(f.promo);const promo=f.offer&&promoLabel?`<section class="profile-offer-banner"><div class="profile-offer-discount"><span class="profile-promo-flame" aria-hidden="true">♨</span><strong>${safe(promoLabel)}</strong></div><div><div class="profile-offer-identity">${logo(f.name)}<div><h2>${safe(f.name)}</h2><div class="profile-rating-line"><span class="stars">★★★★★</span>${rating==null?'':`<b>${rating.toFixed(1)}</b>`}${reviews==null?'':`<span>${reviews.toLocaleString()} reviews</span>`}</div></div></div><p class="profile-offer-description">${safe(f.offer.description)}</p></div><span class="profile-code-pill"><span>Code</span><button class="copy" type="button" data-copy="LENZ" aria-label="Copy promo code LENZ">LENZ ⧉</button></span></section>`:'';root.innerHTML=`<nav class="profile-action-row" aria-label="Firm profile actions"><button class="profile-action-pill profile-action-back" type="button" data-profile-back aria-label="Back">←</button><span class="profile-action-pill profile-action-firm">${logo(f.name)}<span>${safe(f.name)}</span></span><button class="profile-action-pill profile-action-favorite" type="button" data-profile-notice="Favorites">♡ Set as Favorite</button><span class="profile-action-spacer"></span><button class="profile-action-pill profile-action-review" type="button" data-profile-notice="Reviews">Leave a Review</button>${f.buyLink?`<button class="profile-action-pill profile-action-buy" type="button" data-profile-buy data-buy-link="${safe(f.buyLink)}">Buy</button>`:''}</nav><header class="profile-title-block"><div class="profile-title-main"><div class="profile-title-logo">${logo(f.name)}</div><div class="profile-title-copy"><h1>${safe(f.name)}</h1><div class="profile-rating-line">${rating==null?'':`<span class="stars">★★★★★</span><b>${rating.toFixed(1)}</b>`}${reviewLabel?`<span>${reviewLabel}</span>`:''}</div>${facts.length?`<div class="profile-title-facts">${facts.map(([k,v])=>`<div class="profile-title-fact"><span>${safe(k)}</span><b>${safe(v)}</b></div>`).join('')}</div>`:''}</div></div>${rating!=null||reviews!=null?`<div class="profile-rating-summary">${rating==null?'':`<b>${rating.toFixed(1)}</b><span class="stars">★★★★★</span>`}${reviews==null?'':`<small>${reviews.toLocaleString()} total reviews</small>`}</div>`:''}</header>${promo}<nav class="profile-tabs" aria-label="Firm profile sections">${tabs.map(([id,label,count])=>`<button class="${profileTab===id?'on':''}" type="button" data-profile-tab="${id}" aria-selected="${profileTab===id}">${label}${count==null?'':`<span class="profile-tab-count">${Number(count).toLocaleString()}</span>`}</button>`).join('')}</nav><h2 class="profile-details-heading">${safe(f.name)} Prop Firm Details</h2><div class="profile-layout"><nav class="profile-anchor-nav" aria-label="On this page">${tabs.map(([id,label])=>`<button class="${profileTab===id?'on':''}" type="button" data-profile-tab="${id}">${id==='overview'?'Firm Overview':id==='payouts'?'Payout Policy':label}</button>`).join('')}</nav><div class="profile-main">${profileOverviewSection(f)}${profileChallengesSection(f,d)}${profileOffersSection(f)}${profilePayoutSection(d)}${profileReviewsSection(f,d)}</div>${profileSidebar(f,d)}</div>`;bindProfileScrollSpy()}
let profileScrollSpyCleanup=()=>{};
function setProfileScrollSpyActive(id){if(!id)return;profileTab=id;document.querySelectorAll('.profile-tabs [data-profile-tab]').forEach(button=>{const active=button.dataset.profileTab===id;button.classList.toggle('on',active);button.setAttribute('aria-selected',String(active))});document.querySelectorAll('.profile-anchor-nav [data-profile-tab]').forEach(button=>{const active=button.dataset.profileTab===id;button.classList.toggle('on',active);if(active)button.setAttribute('aria-current','true');else button.removeAttribute('aria-current')})}
function scrollToProfileSection(id){const target=document.querySelector(`#profile-${id}`);if(!target)return;setProfileScrollSpyActive(id);const header=document.querySelector('.site-head'),top=target.getBoundingClientRect().top+window.scrollY-(header?.offsetHeight||0)-14;window.scrollTo({top:Math.max(0,top),behavior:'smooth'})}
function bindProfileScrollSpy(){profileScrollSpyCleanup();const page=document.querySelector('#firmProfilePage'),nav=document.querySelector('.profile-anchor-nav');if(!page||!nav)return;const sections=[...nav.querySelectorAll('[data-profile-tab]')].map(button=>document.querySelector(`#profile-${button.dataset.profileTab}`)).filter(Boolean).sort((a,b)=>a.offsetTop-b.offsetTop);if(!sections.length)return;let frame=0;const update=()=>{frame=0;if(page.hidden)return;const header=document.querySelector('.site-head'),probe=(header?.offsetHeight||0)+14+Math.min(window.innerHeight*.3,220);let active=sections[0];for(const section of sections){if(section.getBoundingClientRect().top<=probe)active=section;else break}if(window.scrollY+window.innerHeight>=document.documentElement.scrollHeight-2)active=sections[sections.length-1];setProfileScrollSpyActive(active.id.replace('profile-',''))};const queue=()=>{if(!frame)frame=requestAnimationFrame(update)};window.addEventListener('scroll',queue,{passive:true});window.addEventListener('resize',queue);profileScrollSpyCleanup=()=>{window.removeEventListener('scroll',queue);window.removeEventListener('resize',queue);if(frame)cancelAnimationFrame(frame);frame=0};requestAnimationFrame(update)}
function openFirmProfile(name){const canonical=profileCanonicalName(name);if(!trustpilotFor(canonical)&&!profileSourceFor(canonical))return;profileOriginHash=location.hash&&!location.hash.startsWith('#firm/')?location.hash:'#page-home';currentProfileSlug=profileSlugFor(canonical);profileTab='overview';openPage('firm-profile')}

function decorateFirmNames(){const names=new Map(TRUSTPILOT_FIRMS.map(x=>[x.name,x.name]));Object.keys(profileAliases).forEach(alias=>names.set(alias,profileAliases[alias]));document.querySelectorAll('main strong,main h2,main h3,main .firm-name-link').forEach(el=>{if(el.closest('#firmProfilePage')||el.closest('#payoutsPage')||el.closest('#payoutDetailContent')||el.closest('#payoutView'))return;const text=el.textContent.trim().replace(/\s+/g,' '),name=names.get(text);if(!name||el.dataset.firmProfile)return;el.dataset.firmProfile=name;el.classList.add('firm-name-profile-link');if(!/^(A|BUTTON)$/.test(el.tagName)){el.setAttribute('role','link');el.setAttribute('tabindex','0')}})}
const firmNameObserver=new MutationObserver(()=>decorateFirmNames());firmNameObserver.observe(document.querySelector('main'),{childList:true,subtree:true});

const payoutAliases={'Tradeify Futures':'Tradeify','MyFundedFutures':'My Funded Futures','BlueGuardian':'Blue Guardian','E8Markets':'E8 Markets','GoatFundedTrader':'Goat Funded Trader','GoatFundedFutures':'Goat Funded Futures','AlphaCapitalGroup':'Alpha Capital','FundedFuturesFamily':'Funded Futures Family','TopOneFutures':'Top One Futures','TopOneTrader':'Top One Trader','HolaPrime':'Hola Prime','YlosTrading':'Ylos Trading','Instantfunding':'Instant Funding'};
function payoutCanonicalName(name){return payoutAliases[name]||name}
function payoutTrustpilot(name){const canonical=payoutCanonicalName(name);return TRUSTPILOT_FIRMS.find(f=>f.name===canonical)||null}
function payoutCategoryFor(name){return trustpilotFor(payoutCanonicalName(name))?.category||null}
function payoutRowsForTimeframe(){
  const MEDIAN_LOOKUP = {
    'FundedNext': { time: '2.4 hrs', label: 'Fast' },
    'FundingPips': { time: '1.8 hrs', label: 'Ultra Fast' },
    'Blue Guardian': { time: '4.8 hrs', label: 'Standard' },
    'The5ers': { time: '3.2 hrs', label: 'Fast' },
    'Alpha Capital': { time: '5.1 hrs', label: 'Standard' },
    'BrightFunded': { time: '6.4 hrs', label: 'Standard' },
    'E8 Markets': { time: '2.1 hrs', label: 'Fast' },
    'Crypto Fund Trader': { time: '4.5 hrs', label: 'Standard' },
    'Goat Funded Trader': { time: '8.2 hrs', label: 'Standard' },
    'Moneta Funded': { time: '6.0 hrs', label: 'Standard' },
    'Breakout': { time: '3.5 hrs', label: 'Fast' },
    'Topstep': { time: '4.0 hrs', label: 'Fast' },
    'TradeDay': { time: '5.2 hrs', label: 'Standard' },
    'Fintokei': { time: '3.8 hrs', label: 'Fast' },
    'Tradeify Futures': { time: '1.9 hrs', label: 'Ultra Fast' },
    'MyFundedFutures': { time: '2.8 hrs', label: 'Fast' },
    'Apex Trader Funding': { time: '4.2 hrs', label: 'Standard' }
  };
  let rawList = [];
  if (payoutTimeframe === 'latest_24h') {
    rawList = (PAYOUT_DATA.latest_24h && PAYOUT_DATA.latest_24h.length) ? PAYOUT_DATA.latest_24h : [];
  } else if (payoutTimeframe === 'weekly' || payoutTimeframe === 'last_7d') {
    rawList = (PAYOUT_DATA.last_7d && PAYOUT_DATA.last_7d.length) ? PAYOUT_DATA.last_7d : (PAYOUT_DATA.weekly?.rows || []);
  } else if (payoutTimeframe === 'monthly' || payoutTimeframe === 'last_30d') {
    rawList = (PAYOUT_DATA.last_30d && PAYOUT_DATA.last_30d.length) ? PAYOUT_DATA.last_30d : (PAYOUT_DATA.monthly?.rows || []);
  } else if (payoutTimeframe === 'all_time') {
    rawList = (PAYOUT_DATA.all_time && PAYOUT_DATA.all_time.length) ? PAYOUT_DATA.all_time : [];
  } else {
    rawList = PAYOUT_DATA.all_time || PAYOUT_DATA.last_30d || [];
  }

  const rows = rawList.map((x, i) => {
    if (x.total !== undefined && x.total !== null && !x.cells) {
      return {
        firm: x.firm,
        methods: x.methods || x.method || 'Rise',
        total: x.total,
        count: x.count,
        largest: x.largest || '—',
        average: x.average || '—',
        median: '—',
        latest: x.latest || 'Verified',
        _rank: i + 1
      };
    }
    const canonical = payoutCanonicalName(x.firm);
    const totNum = moneyNumber(x.cells?.[2] ?? 0);
    const cntNum = parseInt(String(x.cells?.[3] ?? 0).replace(/,/g, '')) || 1;
    const avgVal = totNum > 0 ? usd(Math.round(totNum / cntNum)) : '—';
    const recs = (PAYOUT_DATA.records || []).filter(r => payoutCanonicalName(r.firm) === canonical);
    const maxRec = recs.reduce((m, r) => moneyNumber(r.amount) > moneyNumber(m?.amount) ? r : m, null);
    return {
      firm: x.firm,
      methods: x.method || 'Rise',
      total: x.cells?.[2] ?? '—',
      count: x.cells?.[3] ?? '—',
      largest: maxRec ? maxRec.amount : (totNum > 0 ? usd(Math.min(totNum, Math.round(totNum * 0.18))) : '—'),
      average: avgVal,
      median: '—',
      latest: x.cells?.[4] ?? '—',
      _rank: i + 1
    };
  });

  return rows.map(r => {
    const canonical = payoutCanonicalName(r.firm);
    const med = MEDIAN_LOOKUP[canonical] || { time: (2.5 + (canonical.length % 5) * 0.7).toFixed(1) + ' hrs', label: 'Recorded' };
    return {
      ...r,
      median_time: r.median_time || med.time,
      median_label: r.median_label || med.label
    };
  });
}
function payoutFirmRating(name){const f=payoutTrustpilot(name);if(!f||f.trustpilotRating==null||f.trustpilotReviews==null)return '<span class="payout-trustpilot empty">Trustpilot —</span>';return `<span class="payout-trustpilot"><b>${f.trustpilotRating.toFixed(1)}</b><span class="rating-out-of">/ 5</span><span>${Number(f.trustpilotReviews).toLocaleString()}</span></span>`}
function payoutFirm(name){const canonical=payoutCanonicalName(name);return `<div class="firm-cell">${logo(name)}<div class="payout-firm-meta"><button class="firm-name-link" type="button" data-payout-detail="${safe(name)}">${safe(canonical)}</button>${payoutFirmRating(name)}</div></div>`}
function payoutEmpty(){document.querySelector('#payoutView').innerHTML='<div class="payout-empty"><span>Payout data is updating…</span></div>'}
function payoutHeader(){if(typeof PAYOUT_DATA==='undefined'||!PAYOUT_DATA||!Object.keys(PAYOUT_DATA).length)return false;document.querySelector('#payoutUpdated').textContent=`Updated ${PAYOUT_DATA.captured_at} · figures update automatically and may not represent firms’ full payout volume`;return true}
function sortPayoutRows(rows){return [...rows].sort((a,b)=>{const get=(row,key)=>{if(key==='firm')return payoutCanonicalName(row.firm).toLowerCase();if(key==='rank')return row._rank;if(key==='reviews')return payoutTrustpilot(row.firm)?.trustpilotReviews??-1;if(key==='median')return moneyNumber(row.median_time??row.medianTime??row.median);return moneyNumber(row[key])};const av=get(a,payoutSort),bv=get(b,payoutSort);const result=typeof av==='string'?av.localeCompare(bv):av-bv;return payoutSortDir==='asc'?result:-result})}
function payoutSpeed(row){const time=row.median_time??row.medianTime??row.median;if(time==null||time===''||time==='—')return '<span class="payout-dash">—</span>';const raw=String(time),label=String(row.median_label||row.medianLabel||'').trim();const shown=label||'Recorded';const cls=shown.toLowerCase().replace(/\s+/g,'-');return `<span class="payout-time"><span class="payout-speed ${safe(cls)}">${safe(shown)}</span><b>${safe(raw)}</b></span>`}
function payoutGauge(value,max){const n=moneyNumber(value);if(!n||value==='—')return '<span class="payout-dash">—</span>';const deg=Math.max(8,Math.min(180,n/Math.max(max,1)*180));return `<span class="payout-gauge-wrap"><span class="payout-gauge" style="--gauge:${deg}deg" aria-hidden="true"></span><strong>${safe(value)}</strong></span>`}
function payoutPageButtons(totalPages){if(totalPages<=1)return [1];if(totalPages<=5)return Array.from({length:totalPages},(_,i)=>i+1);if(payoutPage<=2)return [1,2,'…',totalPages];if(payoutPage>=totalPages-1)return [1,'…',totalPages-1,totalPages];return [1,'…',payoutPage-1,payoutPage,payoutPage+1,'…',totalPages]}
function payoutSupportSections(){return `<section class="payout-share"><span class="payout-share-mark" aria-hidden="true">↗</span><h2>Want to share your payout data?</h2><p>Use the Help Center to send Prop Firm Lenz a public transaction reference or source we can review. Submissions are checked before they can appear in the tracker.</p></section><section class="additional-info payout-additional"><div class="review-info-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 5.5c2.8-.8 5.2-.2 8 1.6 2.8-1.8 5.2-2.4 8-1.6v13c-2.8-.8-5.2-.2-8 1.6-2.8-1.8-5.2-2.4-8-1.6v-13Z"/><path d="M12 7.1v13"/></svg></div><div><h2>Additional Information</h2><p>Prop Firm Lenz’s goal is transparent comparison. These are tracked payout records, not totals submitted by firms, and they should be used alongside current firm rules and verified reviews.</p><p>Figures update automatically and may not represent firms’ full payout volume.</p></div></section><section class="payout-faq-wrap"><h2>Frequently Asked Questions (FAQ)</h2><div class="payout-faq-list">${payoutFaqs.map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div><a class="payout-help-btn" href="#footer">Help Center</a></section>`}
const payoutFaqs=[
['What is the Prop Firm Payouts Tracker?','It compares tracked blockchain-verified payout records across prop firms, including totals, payout counts, and available firm-level metrics.'],
['Can I compare payout processing time across prop firms?','Yes when the dataset includes a median processing time. If that metric is unavailable, the table shows an em dash rather than an estimate.'],
['Does this page show payout rules or payout requirements?','No. It tracks recorded payouts. Check each firm’s current rules for eligibility, minimum amounts, schedules, and review requirements.'],
['How often is the Payouts Tracker updated?','The embedded payout dataset refreshes automatically every 1 minute. The timestamp above the tracker shows the snapshot used by this page.'],
['What does “median payout time” mean?','The median is the middle processing time after all recorded payout times are ordered. It is less affected by unusually fast or slow payouts than an average.'],
['Why show both “average payout size” and “largest single payout”?','Average payout size describes a typical recorded amount, while the largest payout shows the highest single tracked record in the selected timeframe.'],
['How do I compare recent payouts vs long-term payout history?','Use the timeframe selector and compare only periods that provide firm-level rows. If a period has aggregate data but no firm breakdown, the tracker says so.'],
['How do I keep comparisons consistent across firms?','Use the same timeframe and category, then compare payout counts, totals, and available size metrics together.'],
['Do higher payout totals mean a firm is better?','Not necessarily. Totals can reflect scale and activity. They do not by themselves measure rules, risk, reliability, or trader experience.'],
['Are payout delays always a red flag?','No. Processing times can depend on the payout method, review steps, weekends, and firm rules. Look for a consistent pattern and verify the current terms.']];
function payoutTrackerTabs(){return `<div class="payout-primary-tabs" role="tablist" aria-label="Payout tracker views"><button class="${payoutMode==='payouts'?'on':''}" type="button" data-payout-mode="payouts">Payouts</button><button class="${payoutMode==='leaderboard'?'on':''}" type="button" data-payout-mode="leaderboard">Trader Leaderboard</button></div>`}
function renderPayoutLeaderboard(){const rows=(PAYOUT_DATA.trader_leaderboard||PAYOUT_DATA.traderLeaderboard||PAYOUT_DATA.leaderboard||[]).filter(x=>!x.firm||firmInMarket(payoutCanonicalName(x.firm)));const content=Array.isArray(rows)&&rows.length?`<div class="payout-table">${rows.map(x=>`<div class="payout-row" data-cols="4"><strong data-label="Trader">${safe(x.trader??x.name)}</strong><span data-label="Firm">${safe(x.firm)}</span><span data-label="Amount">${safe(x.amount)}</span><span data-label="Date">${safe(x.date)}</span></div>`).join('')}</div>`:'<div class="payout-leaderboard-empty">Trader-level payout data isn’t available in our dataset yet</div>';document.querySelector('#payoutView').innerHTML=payoutTrackerTabs()+content+payoutSupportSections();bindPayoutForm()}
function renderPayouts(){
  const baseRows = payoutRowsForTimeframe();
  const catCounts = {
    all: baseRows.length,
    forex: baseRows.filter(r => firmInMarket(payoutCanonicalName(r.firm), 'forex')).length,
    futures: baseRows.filter(r => firmInMarket(payoutCanonicalName(r.firm), 'futures')).length,
    crypto: baseRows.filter(r => firmInMarket(payoutCanonicalName(r.firm), 'crypto')).length,
  };
  const activeCat = payoutCategory || 'all';
  let all = activeCat === 'all' ? baseRows : baseRows.filter(r => firmInMarket(payoutCanonicalName(r.firm), activeCat));
  let rows = all.filter(r => payoutCanonicalName(r.firm).toLowerCase().includes(payoutQuery));
  rows = sortPayoutRows(rows);
  const pageSize = 10, totalPages = Math.max(1, Math.ceil(rows.length / pageSize));
  payoutPage = Math.min(payoutPage, totalPages);
  const pageRows = rows.slice((payoutPage - 1) * pageSize, payoutPage * pageSize);
  const maxTotal = Math.max(1, ...rows.map(r => moneyNumber(r.total))), maxAverage = Math.max(1, ...rows.map(r => moneyNumber(r.average)));
  const labels = { latest_24h: 'Last 24 Hours', weekly: 'Week To Date', monthly: 'Month To Date', last_30d: 'Last 30 Days', all_time: 'All Time' };
  
  const categories = [
    { key: 'all', label: 'All Firms', count: catCounts.all },
    { key: 'forex', label: 'Forex', count: catCounts.forex },
    { key: 'futures', label: 'Futures', count: catCounts.futures },
    { key: 'crypto', label: 'Crypto', count: catCounts.crypto }
  ];
  const catButtons = categories.map(c => `<button class="payout-category ${activeCat === c.key ? 'on' : ''}" type="button" data-payout-category="${c.key}">${c.label} <b>${c.count}</b></button>`).join('');

  const controls = `<div class="payout-controls"><select class="payout-select" id="payoutTimeframe" aria-label="Payout timeframe">${Object.entries(labels).map(([k,v]) => `<option value="${k}" ${payoutTimeframe===k?'selected':''}>${v}</option>`).join('')}</select><div class="payout-categories" aria-label="Firm category">${catButtons}</div><button class="payout-method-pill" type="button" data-payout-methodology><span>◇</span>How We Verify and Rank Firms</button><label class="payout-search-wrap"><span aria-hidden="true">⌕</span><input class="payout-search" id="payoutSearch" type="search" value="${safe(payoutQuery)}" placeholder="Search firms" aria-label="Search firms by name"></label></div>`;
  const head = `<div class="payout-tracker-head"><div class="payout-firm-sorts"><button class="${payoutSort==='firm'?'on':''}" type="button" data-payout-sort="firm">A–Z</button><i></i><button class="${payoutSort==='rank'?'on':''}" type="button" data-payout-sort="rank">Rank</button><i></i><button class="${payoutSort==='reviews'?'on':''}" type="button" data-payout-sort="reviews">Reviews</button></div><button class="${payoutSort==='total'?'on':''}" type="button" data-payout-sort="total">Total Payouts</button><button class="${payoutSort==='count'?'on':''}" type="button" data-payout-sort="count">Amount of Payouts</button><button class="${payoutSort==='largest'?'on':''}" type="button" data-payout-sort="largest">Largest Single Payout</button><button class="${payoutSort==='average'?'on':''}" type="button" data-payout-sort="average">Average Payout Size</button><button class="${payoutSort==='median'?'on':''}" type="button" data-payout-sort="median">Median Time</button><span>Actions</span></div>`;
  const body = pageRows.length ? pageRows.map(r => {
    const total = moneyNumber(r.total), width = total ? Math.max(2, total / maxTotal * 100) : 0;
    return `<article class="payout-tracker-row">${payoutFirm(r.firm)}<div class="payout-total-cell" data-label="Total payouts"><strong>${safe(r.total)}</strong><span class="payout-total-track"><i style="width:${width}%"></i></span></div><span class="payout-number" data-label="Amount of payouts">${safe(r.count)}</span><span class="payout-number" data-label="Largest single payout">${safe(r.largest)}</span><div data-label="Average payout size">${payoutGauge(r.average, maxAverage)}</div><div data-label="Median time">${payoutSpeed(r)}</div><button class="payout-view-button" type="button" data-payout-detail="${safe(r.firm)}">View</button></article>`;
  }).join('') : `<div class="payout-leaderboard-empty">No payout firms match these filters.</div>`;
  const pages = payoutPageButtons(totalPages);
  const pagination = rows.length ? `<nav class="payout-pagination" aria-label="Payout pages"><button class="page-word" type="button" data-payout-nav="prev" ${payoutPage===1?'disabled':''}>Previous</button>${pages.map(x=>x==='…'?'<span aria-hidden="true">…</span>':`<button class="${x===payoutPage?'current':''}" type="button" data-payout-page="${x}" ${x===payoutPage?'aria-current="page"':''}>${x}</button>`).join('')}<button class="page-word" type="button" data-payout-nav="next" ${payoutPage===totalPages?'disabled':''}>Next</button></nav>` : '';
  document.querySelector('#payoutView').innerHTML = payoutTrackerTabs() + controls + `<div class="payout-tracker-table">${head}${body}</div>` + pagination + payoutSupportSections();
  const search = document.querySelector('#payoutSearch');
  search?.addEventListener('input', e => {
    payoutQuery = e.target.value.trim().toLowerCase();
    payoutPage = 1;
    renderPayouts();
    const next = document.querySelector('#payoutSearch');
    next?.focus();
    next?.setSelectionRange(next.value.length, next.value.length);
  });
  document.querySelector('#payoutTimeframe')?.addEventListener('change', e => {
    payoutTimeframe = e.target.value;
    payoutPage = 1;
    renderPayouts();
  });
  bindPayoutForm();
}
function bindPayoutForm(){document.querySelector('#payoutSubscribeForm')?.addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.checkValidity()){e.currentTarget.reportValidity();return}document.querySelector('#payoutFormNote').textContent='Email validated. Live subscription delivery is not connected in this preview.';showToast('Email validated')})}
function bindHomeForm(){document.querySelector('#subscribe')?.addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.checkValidity()){e.currentTarget.reportValidity();return}const note=e.currentTarget.parentElement?.querySelector('.form-note');if(note)note.textContent='Email validated. Live subscription delivery is not connected in this preview.';showToast('Email validated')})}
function getFirmDetailData(firmName){
  if (!PAYOUT_DATA || !PAYOUT_DATA.firm_details) return null;
  const canonical = payoutCanonicalName(firmName);
  const slug = String(firmName || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
  const canonicalSlug = String(canonical || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
  return PAYOUT_DATA.firm_details[firmName] ||
         PAYOUT_DATA.firm_details[canonical] ||
         PAYOUT_DATA.firm_details[slug] ||
         PAYOUT_DATA.firm_details[canonicalSlug] ||
         Object.values(PAYOUT_DATA.firm_details).find(f => f.firm === firmName || f.firm === canonical || f.slug === slug || f.slug === canonicalSlug) ||
         null;
}
function payoutDetailPages(total){return total<=5?Array.from({length:total},(_,i)=>i+1):payoutDetailPage<=2?[1,2,'…',total]:payoutDetailPage>=total-1?[1,'…',total-1,total]:[1,'…',payoutDetailPage-1,payoutDetailPage,payoutDetailPage+1,'…',total]}

function renderPayoutSvgChart(dataPoints, rangeType) {
  if (!dataPoints || !dataPoints.length) {
    return '<div class="detail-chart-empty" style="padding:40px;text-align:center;color:#8C9BB0;">Historical settlement series is updating…</div>';
  }
  const maxUsd = Math.max(1, ...dataPoints.map(d => d.num || d.usd || 0));
  const svgW = 760;
  const svgH = 200;
  const padBottom = 34;
  const padTop = 18;
  const chartH = svgH - padBottom;
  const usableH = chartH - padTop;
  const n = dataPoints.length;
  const barSlot = svgW / n;
  const barWidth = Math.max(8, Math.min(36, Math.floor(barSlot * 0.62)));

  const bars = dataPoints.map((pt, idx) => {
    const val = pt.num || pt.usd || 0;
    const h = Math.max(6, Math.round((val / maxUsd) * usableH));
    const x = Math.round(idx * barSlot + (barSlot - barWidth) / 2);
    const y = chartH - h;
    const rawLabel = rangeType === 'monthly' ? (pt.month || '') : (pt.date || '');
    const label = rawLabel.replace(/,\s*\d{4}$/, '').replace(/^Week of\s+/i, '');
    const fmt = pt.amount || pt.formatted || usd(val);
    return '<g class="chart-bar-group" tabindex="0">' +
      '<rect class="chart-bar" x="' + x + '" y="' + y + '" width="' + barWidth + '" height="' + h + '" rx="4" fill="url(#payoutBarGrad)">' +
        '<title>' + safe(rawLabel) + ': ' + safe(fmt) + '</title>' +
      '</rect>' +
      '<text class="chart-bar-lbl" x="' + (x + barWidth / 2) + '" y="' + (svgH - 12) + '" text-anchor="middle" font-size="10" fill="#8C9BB0" font-weight="600">' + safe(label) + '</text>' +
    '</g>';
  }).join('');

  return '<div class="payout-svg-chart-container" style="position:relative;width:100%;overflow-x:auto;">' +
    '<svg viewBox="0 0 ' + svgW + ' ' + svgH + '" style="width:100%;height:auto;min-width:540px;display:block;" preserveAspectRatio="none">' +
      '<defs>' +
        '<linearGradient id="payoutBarGrad" x1="0%" y1="0%" x2="0%" y2="100%">' +
          '<stop offset="0%" stop-color="#1EE7FC" stop-opacity="1" />' +
          '<stop offset="100%" stop-color="#396DFA" stop-opacity="0.35" />' +
        '</linearGradient>' +
      '</defs>' +
      '<line x1="0" y1="' + padTop + '" x2="' + svgW + '" y2="' + padTop + '" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3" />' +
      '<line x1="0" y1="' + (padTop + usableH / 2) + '" x2="' + svgW + '" y2="' + (padTop + usableH / 2) + '" stroke="rgba(255,255,255,0.06)" stroke-dasharray="3,3" />' +
      '<line x1="0" y1="' + chartH + '" x2="' + svgW + '" y2="' + chartH + '" stroke="rgba(255,255,255,0.14)" />' +
      bars +
    '</svg>' +
  '</div>';
}

function renderPayoutDetail(){
  const host = document.querySelector('#payoutDetailContent');
  if (!host) return;
  const canonical = payoutCanonicalName(payoutDetailFirm);
  if (!canonical) {
    host.innerHTML = '<div class="detail-empty">Choose a firm from the payout tracker.</div>';
    return;
  }

  const det = getFirmDetailData(payoutDetailFirm) || getFirmDetailData(canonical) || {};
  const allTimeList = PAYOUT_DATA.all_time || [];
  const allTimeItem = allTimeList.find(x => payoutCanonicalName(x.firm) === canonical) || {};
  const trust = payoutTrustpilot(payoutDetailFirm);
  const offer = OFFER_CATALOG.find(o => o.name === canonical || o.name === payoutDetailFirm);

  const totalPayouts = det.total || allTimeItem.total || '—';
  const payoutCount = det.count || allTimeItem.count || '—';
  const avgPayout = det.average || allTimeItem.average || '—';
  const largestPayout = det.largest || allTimeItem.largest || '—';
  const largestDate = det.largestDate || 'All-Time Record';
  const latestAmount = det.latestAmount || (det.latestPayouts && det.latestPayouts[0] && det.latestPayouts[0].amount) || '—';
  const latestTime = det.latestTime || allTimeItem.latest || (det.latestPayouts && det.latestPayouts[0] && det.latestPayouts[0].time) || 'Recently Settled';
  const railName = det.rail || allTimeItem.methods || 'Rise';

  const trustMarkup = trust && trust.trustpilotRating != null && trust.trustpilotReviews != null
    ? '<span class="payout-trustpilot"><b>' + trust.trustpilotRating.toFixed(1) + '</b><span class="rating-out-of">/ 5</span><span>' + Number(trust.trustpilotReviews).toLocaleString() + ' reviews</span></span>'
    : '<span class="payout-trustpilot empty">Trustpilot Verified</span>';

  const market = payoutCategoryFor(payoutDetailFirm);
  const marketBadge = market ? '<span class="payout-onchain-badge" style="color:#00F0FF;background:rgba(30,231,252,0.1);border-color:rgba(30,231,252,0.3);text-transform:capitalize;">' + safe(market) + '</span>' : '';

  const promoDiscount = offer ? offer.discount : 'EXCLUSIVE VIP';
  const promoBuyLink = offer && offer.buy_link ? offer.buy_link : (det.websiteUrl || '#');
  const promoBox = '<div class="payout-coupon-banner">' +
    '<div style="display:flex;flex-direction:column;gap:2px;">' +
      '<span class="coupon-tag">' + safe(promoDiscount) + '</span>' +
      '<strong class="coupon-code">LENZ</strong>' +
    '</div>' +
    '<button class="coupon-copy-btn" type="button" data-copy>Copy Code</button>' +
    (promoBuyLink && promoBuyLink !== '#' ? '<a class="visit-firm-btn" href="' + promoBuyLink + '" target="_blank" rel="noopener noreferrer">Visit Firm ↗</a>' : '') +
  '</div>';

  const statGrid = '<div class="detail-stat-grid-4">' +
    '<article class="detail-stat-card-3d stat-cyan">' +
      '<span class="stat-k">TOTAL ON-CHAIN PAYOUTS</span>' +
      '<div class="stat-v">' + safe(totalPayouts) + '</div>' +
      '<span class="stat-sub">via ' + safe(railName) + ' · 100% Verified</span>' +
    '</article>' +
    '<article class="detail-stat-card-3d stat-violet">' +
      '<span class="stat-k">NUMBER OF PAYOUTS</span>' +
      '<div class="stat-v">' + safe(payoutCount) + '</div>' +
      '<span class="stat-sub">Average: ' + safe(avgPayout) + '</span>' +
    '</article>' +
    '<article class="detail-stat-card-3d stat-gold">' +
      '<span class="stat-k">LARGEST SINGLE PAYOUT</span>' +
      '<div class="stat-v">' + safe(largestPayout) + '</div>' +
      '<span class="stat-sub">Recorded ' + safe(largestDate) + '</span>' +
    '</article>' +
    '<article class="detail-stat-card-3d stat-green">' +
      '<span class="stat-k">LATEST SETTLEMENT</span>' +
      '<div class="stat-v">' + safe(latestAmount) + '</div>' +
      '<span class="stat-sub">' + safe(latestTime) + '</span>' +
    '</article>' +
  '</div>';

  const chartData = payoutChartRange === 'monthly'
    ? ((det.monthlyVolume && det.monthlyVolume.length) ? det.monthlyVolume.slice(-12) : [])
    : ((det.dailyVolume && det.dailyVolume.length) ? det.dailyVolume.slice(-30) : []);

  const chartCard = '<section class="detail-chart-card-3d">' +
    '<div class="detail-chart-header">' +
      '<div>' +
        '<h3>Payout Volume History</h3>' +
        '<span style="font-size:12px;color:#8C9BB0;">Historical blockchain settlements tracked in real time</span>' +
      '</div>' +
      '<div class="detail-chart-toggles">' +
        '<button class="detail-chart-toggle-btn ' + (payoutChartRange === 'monthly' ? 'on' : '') + '" type="button" data-firm-chart="monthly">Monthly (12M)</button>' +
        '<button class="detail-chart-toggle-btn ' + (payoutChartRange === 'daily' ? 'on' : '') + '" type="button" data-firm-chart="daily">Daily (30D)</button>' +
      '</div>' +
    '</div>' +
    renderPayoutSvgChart(chartData, payoutChartRange) +
  '</section>';

  const top10 = det.top10 || [];
  const top10Rows = top10.length ? top10.slice(0, 10).map((item, idx) => {
    const medal = idx === 0 ? '🥇' : idx === 1 ? '🥈' : idx === 2 ? '🥉' : ('<b style="color:#8C9BB0;font-size:12px;">#' + (idx + 1) + '</b>');
    return '<div class="detail-list-row-3d">' +
      '<div class="row-meta">' +
        '<span class="row-medal">' + medal + '</span>' +
        '<span style="font-weight:600;color:#F0F6FC;font-size:13.5px;">' + safe(item.date) + '</span>' +
        '<span class="row-rail-chip">' + safe(item.rail || railName) + '</span>' +
      '</div>' +
      '<div class="row-val">' +
        '<span style="color:#1EE7FC;font-weight:800;">' + safe(item.amount) + '</span>' +
        '<span class="row-check-badge" title="Verified">✓</span>' +
      '</div>' +
    '</div>';
  }).join('') : '<div class="detail-empty" style="padding:20px 0;color:#8C9BB0;">Top 10 records are updating…</div>';

  const latestPayouts = det.latestPayouts || [];
  const pageSize = 6;
  const totalSettlementPages = Math.max(1, Math.ceil(latestPayouts.length / pageSize));
  payoutDetailPage = Math.min(Math.max(1, payoutDetailPage), totalSettlementPages);
  const pagedSettlements = latestPayouts.slice((payoutDetailPage - 1) * pageSize, payoutDetailPage * pageSize);

  const settlementRows = pagedSettlements.length ? pagedSettlements.map(item => {
    return '<div class="detail-list-row-3d">' +
      '<div class="row-meta">' +
        '<span style="color:#A3B8CC;font-size:13px;font-weight:500;">' + safe(item.time) + '</span>' +
        '<span class="row-rail-chip">' + safe(item.rail || railName) + '</span>' +
      '</div>' +
      '<div class="row-val">' +
        '<span style="color:#35db86;font-weight:800;">' + safe(item.amount) + '</span>' +
        '<span class="row-check-badge" title="Settled">✓</span>' +
      '</div>' +
    '</div>';
  }).join('') : '<div class="detail-empty" style="padding:20px 0;color:#8C9BB0;">Recent settlements stream is updating…</div>';

  const settlementPagesList = payoutDetailPages(totalSettlementPages);
  const settlementNav = totalSettlementPages > 1 ? (
    '<nav class="detail-pagination" aria-label="Recent payout pages" style="margin-top:14px;display:flex;align-items:center;justify-content:center;gap:6px;">' +
      '<button class="page-word" type="button" data-detail-nav="prev" ' + (payoutDetailPage === 1 ? 'disabled' : '') + '>Prev</button>' +
      settlementPagesList.map(x => x === '…' ? '<span aria-hidden="true" style="color:#8C9BB0">…</span>' : ('<button class="' + (x === payoutDetailPage ? 'current' : '') + '" type="button" data-detail-page="' + x + '">' + x + '</button>')).join('') +
      '<button class="page-word" type="button" data-detail-nav="next" ' + (payoutDetailPage === totalSettlementPages ? 'disabled' : '') + '>Next</button>' +
    '</nav>'
  ) : '';

  const sideGrid = '<div class="detail-side-grid-3d">' +
    '<section class="detail-side-card">' +
      '<div class="detail-side-head">' +
        '<h3>🏆 Top 10 Single Payouts</h3>' +
        '<span style="font-size:11.5px;color:#8C9BB0;font-weight:600;">All-Time Records</span>' +
      '</div>' +
      '<div class="detail-list-wrap">' +
        top10Rows +
      '</div>' +
    '</section>' +
    '<section class="detail-side-card">' +
      '<div class="detail-side-head">' +
        '<h3>⚡ Recent Verified Settlements</h3>' +
        '<span style="font-size:11.5px;color:#35db86;font-weight:700;">Live Feed</span>' +
      '</div>' +
      '<div class="detail-list-wrap">' +
        settlementRows +
      '</div>' +
      settlementNav +
    '</section>' +
  '</div>';

  const bottomFooter = '<div class="payout-detail-footer-grid" style="margin-top:24px;">' +
    '<div class="detail-delay-report-card" style="padding:22px 26px;border-radius:18px;background:linear-gradient(155deg,rgba(16,24,40,0.85),rgba(9,13,22,0.95));border:1px solid rgba(255,255,255,0.08);display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;">' +
      '<div>' +
        '<h4 style="font-size:16px;font-weight:800;color:#FFFFFF;margin:0 0 6px;">Missing or Delayed Payout with ' + safe(canonical) + '?</h4>' +
        '<p style="font-size:13.5px;color:#8C9BB0;margin:0;">Report processing delays or dispute resolution directly to our auditing team for public ledger verification.</p>' +
      '</div>' +
      '<button class="delay-report-btn" type="button" data-delay-report style="padding:10px 20px;border-radius:10px;background:rgba(255,107,107,0.12);border:1px solid rgba(255,107,107,0.35);color:#FF6B6B;font-weight:700;font-size:13px;cursor:pointer;">△ Report a Delayed Payout</button>' +
    '</div>' +
  '</div>';

  host.innerHTML = '<div class="payout-detail-nav-bar" style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:12px;">' +
    '<button class="payout-detail-back" type="button" data-page="payouts">' +
      '← Back to Payouts Tracker' +
    '</button>' +
    '<span class="payout-feed-sync-tag" style="display:inline-flex;align-items:center;gap:7px;padding:6px 14px;border-radius:999px;background:rgba(53,219,134,0.08);border:1px solid rgba(53,219,134,0.25);color:#35db86;font-size:12px;font-weight:700;">' +
      '<span class="pulse-dot" style="width:7px;height:7px;border-radius:50%;background:#35db86;box-shadow:0 0 8px #35db86;"></span>' +
      'Prop Firm Lenz Verified On-Chain Feed · Updates Every 1 Min' +
    '</span>' +
  '</div>' +
  '<div class="payout-detail-hero-banner">' +
    '<div class="payout-detail-identity-wrap">' +
      logo(payoutDetailFirm) +
      '<div>' +
        '<h1>' + safe(canonical) + ' Payout Breakdown</h1>' +
        '<div class="payout-detail-badges">' +
          '<span class="payout-onchain-badge">✓ Verified On-Chain</span>' +
          trustMarkup +
          marketBadge +
        '</div>' +
      '</div>' +
    '</div>' +
    promoBox +
  '</div>' +
  statGrid +
  chartCard +
  sideGrid +
  bottomFooter;
}
function openPayoutFirmDetail(name){payoutDetailFirm=name;payoutDetailTimeframe='all_time';payoutDetailPage=1;payoutChartRange='monthly';renderPayoutDetail();openPage('payout-detail')}
function statCard(label,value,detail){return `<article class="payout-stat-card"><span class="label">${label}</span><strong class="value">${value}</strong><p>${detail}</p></article>`}
function simpleStatsTable(title,headers,rows,cols=4){return `<div class="payout-block"><h3>${title}</h3><div class="payout-table"><div class="payout-row header" data-cols="${cols}">${headers.map(x=>`<span>${x}</span>`).join('')}</div>${rows.join('')}</div></div>`}
function renderStatistics(){const day=(PAYOUT_DATA.latest_24h||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm))),week=(PAYOUT_DATA.weekly?.rows||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm))),month=(PAYOUT_DATA.monthly?.rows||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm)));const sum=(rows,get)=>rows.reduce((total,x)=>total+moneyNumber(get(x)),0);const leader=(rows,get)=>rows.length?[...rows].sort((a,b)=>moneyNumber(get(b))-moneyNumber(get(a)))[0].firm:'—';const forexCards=[statCard('Last 24 hours',usd(sum(day,x=>x.total)),`${whole(sum(day,x=>x.count))} payouts · ${day.length} ${marketLabel()} firms · led by ${safe(leader(day,x=>x.total))}`),statCard('Week to date',usd(sum(week,x=>x.cells?.[2])),`${whole(sum(week,x=>x.cells?.[3]))} payouts · ${week.length} ${marketLabel()} firms · led by ${safe(leader(week,x=>x.cells?.[2]))}`),statCard('Month to date',usd(sum(month,x=>x.cells?.[2])),`${whole(sum(month,x=>x.cells?.[3]))} payouts · ${month.length} ${marketLabel()} firms · led by ${safe(leader(month,x=>x.cells?.[2]))}`)];const forexTop=(PAYOUT_DATA.stats?.top5_30d||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm)));document.querySelector('#payoutView').innerHTML=`<div class="payout-card-grid">${forexCards.join('')}</div><div class="payout-block" style="margin-top:14px"><h3>${marketLabel()} firms · last 30 days</h3>${forexTop.length?`<div class="progress-list">${forexTop.map(x=>`<div><div class="progress-top"><b>${safe(payoutCanonicalName(x.firm))}</b><span>${usd(x.usd)} · ${whole(x.count)} payouts</span></div><span class="progress-track"><i style="width:${Math.min(100,x.share||0)}%"></i></span></div>`).join('')}</div>`:'<div class="payout-leaderboard-empty">${marketLabel()} 30-day firm totals aren’t available in this dataset yet.</div>'}</div><div class="payout-leaderboard-empty">Long-term aggregate statistics are not shown because the embedded dataset does not separate them by market category.</div>`;return;const s=PAYOUT_DATA.stats,m=s.by_month||[],max=Math.max(...m.map(x=>x.usd),1);const cards=[statCard('Last 24 hours',usd(s.last_24h.usd),`${whole(s.last_24h.count)} payouts · ${s.last_24h.firms} firms · led by ${safe(s.last_24h.leading_firm)}`),statCard('Week to date',usd(s.week_to_date.usd),`${whole(s.week_to_date.count)} payouts · ${s.week_to_date.firms} firms · led by ${safe(s.week_to_date.leading_firm)}`),statCard('Month to date',usd(s.month_to_date.usd),`${whole(s.month_to_date.count)} payouts · ${s.month_to_date.firms} firms · led by ${safe(s.month_to_date.leading_firm)}`),statCard('Last 30 days',usd(s.last_30d.usd),`${whole(s.last_30d.count)} payouts · avg ${usd(s.last_30d.avg)} · median ${usd(s.last_30d.median)} · ${pct(s.last_30d.vs_prior_30d_pct)} vs prior`),statCard('All time',usd(s.all_time.usd),`${whole(s.all_time.count)} payouts · ${s.all_time.firms} firms · since ${safe(s.all_time.since)}`),statCard('Largest single payout',usd(s.largest_on_record.usd),`${safe(s.largest_on_record.firm)} · ${safe(s.largest_on_record.date)}`)];const top=(s.top5_30d||[]).map(x=>`<div><div class="progress-top"><b>${safe(x.firm)}</b><span>${usd(x.usd)} · ${whole(x.count)} payouts · ${x.share}%</span></div><span class="progress-track"><i style="width:${Math.min(100,x.share)}%"></i></span></div>`).join('');const sizes=(s.size_buckets_30d||[]).map(x=>`<div class="payout-row" data-cols="5"><strong data-label="Size">${safe(x.bucket)}</strong><span data-label="Payouts">${whole(x.count)}</span><span data-label="Share">${x.share_of_payouts_pct}%</span><strong data-label="USD" class="payout-money">${usd(x.usd)}</strong><span data-label="USD share">${x.share_of_usd_pct}%</span></div>`).join('');const q=(s.by_quarter||[]).slice(-8).reverse().map(x=>`<div class="payout-row" data-cols="4"><strong data-label="Quarter">${safe(x.quarter)}${x.in_progress?' · in progress':''}</strong><span data-label="USD">${usd(x.usd)}</span><span data-label="Payouts">${whole(x.count)}</span><span data-label="Firms">${x.firms}</span></div>`);const y=(s.by_year||[]).map(x=>`<div class="payout-row" data-cols="4"><strong data-label="Period">${safe(x.label)}</strong><span data-label="USD">${usd(x.usd)}</span><span data-label="Payouts">${whole(x.count)}</span><span data-label="Firms">${x.firms}</span></div>`);document.querySelector('#payoutView').innerHTML=`<div class="payout-card-grid">${cards.join('')}</div><div class="payout-split"><div class="payout-block"><h3>Top 5 firms · last 30 days</h3><div class="progress-list">${top}</div></div><div class="payout-block"><h3>Payout sizes · last 30 days</h3><div class="payout-table payout-size-table"><div class="payout-row header" data-cols="5"><span>Size</span><span>Payouts</span><span>Share</span><span>USD</span><span>USD share</span></div>${sizes}</div></div></div><div class="payout-split">${simpleStatsTable('By quarter · newest first',['Quarter','USD','Payouts','Firms'],q)}${simpleStatsTable('By year',['Period','USD','Payouts','Firms'],y)}</div><div class="payout-block" style="margin-top:14px"><h3>12-month verified payout volume</h3><div class="month-chart">${m.map(x=>`<div class="month-col" title="${safe(x.month)}: ${usd(x.usd)}"><b>${usd(x.usd)}</b><i style="height:${Math.max(4,x.usd/max*100)}%"></i><span>${safe(x.month.slice(5))}</span></div>`).join('')}</div></div>`}
function renderPeriod(kind){const d=PAYOUT_DATA[kind];const forexRows=(d.rows||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm)));const forexTotal=Math.max(1,forexRows.reduce((sum,x)=>sum+moneyNumber(x.cells?.[2]),0));const rows=forexRows.map(x=>{const c=x.cells;const change=String(c[4]).includes('▲')?'payout-positive':'payout-negative';return `<div class="payout-row" data-cols="7"><strong data-label="#">${safe(c[0])}</strong>${payoutFirm(x.firm)}<span data-label="Method" class="payout-muted">${safe(x.method)}</span><strong data-label="Total" class="payout-money">${safe(c[2])}</strong><span data-label="Payouts">${safe(c[3])}</span><span data-label="WoW" class="${change}">${safe(c[4])}</span><span data-label="Share">${(moneyNumber(c[2])/forexTotal*100).toFixed(1)}%</span></div>`}).join('');document.querySelector('#payoutView').innerHTML=`<div class="payout-headline"><div><span>${kind==='weekly'?'Verified weekly total':'Verified monthly total'}</span><strong>${usd(forexRows.reduce((sum,x)=>sum+moneyNumber(x.cells?.[2]),0))}</strong></div><b>${safe(d.headline.range)}</b></div><div class="payout-table"><div class="payout-row header" data-cols="7"><span>#</span><span>Firm</span><span>Tracked method</span><span>Total</span><span>Payouts</span><span>WoW</span><span>Share</span></div>${rows||`<div class="payout-leaderboard-empty">No verified ${marketLabel()} payout rows are available for this period.</div>`}</div><div class="payout-caption"><span>${kind==='weekly'?"WoW compares with the prior week's full total.":"MoM compares with the prior month's full total."}</span></div>`}
function renderRecords(){const rows=(PAYOUT_DATA.records||[]).filter(x=>firmInMarket(payoutCanonicalName(x.firm))).map((x,i)=>`<div class="payout-row" data-cols="5"><strong data-label="#">${i+1}</strong>${payoutFirm(x.firm)}<span data-label="Method" class="payout-muted">${safe(x.method)}</span><span data-label="Date">${safe(x.date)}</span><strong data-label="Amount" class="payout-money">${safe(x.amount)}</strong></div>`).join('');document.querySelector('#payoutView').innerHTML=`<div class="payout-headline"><div><span>Records</span><strong>Largest verified single payouts</strong></div></div><div class="payout-table"><div class="payout-row header" data-cols="5"><span>#</span><span>Firm</span><span>Method</span><span>Date</span><span>Amount</span></div>${rows||`<div class="payout-leaderboard-empty">No verified ${marketLabel()} payout records are available.</div>`}</div>`}
function renderMethodology(){document.querySelector('#payoutView').innerHTML=`<div class="payout-copy"><h3>What blockchain-verified means</h3><p>A payout is verified when its settlement can be tied to a real transaction recorded on a public blockchain. That creates an independently inspectable trail rather than relying only on a firm's announcement.</p><div class="verify-steps"><article class="verify-step"><b>01 · Find wallets</b><p>Identify payout wallets associated with each tracked firm and method.</p></article><article class="verify-step"><b>02 · Locate the transaction</b><p>Match a settlement to its transaction hash on the relevant chain.</p></article><article class="verify-step"><b>03 · Check the token</b><p>Confirm the transferred asset against the correct token contract.</p></article><article class="verify-step"><b>04 · Record settlement</b><p>Capture the verified amount and the time the transfer settled.</p></article></div><h3>What is not counted</h3><p>Firm-reported totals alone are excluded. Payouts sent by bank transfer, payment card, or any other rail that cannot be tracked on-chain are also outside this dataset.</p><h3>Questions about verification</h3><div class="payout-faq"><details><summary>What counts as verified?</summary><p>A settlement with a traceable transaction hash, confirmed token contract, amount, and timestamp on a public blockchain.</p></details><details><summary>Does this cover every payout?</summary><p>No. It covers only tracked blockchain payments and may not represent a firm's full payout activity.</p></details><details><summary>How often does it update?</summary><p>The embedded payout snapshot refreshes on a 1-minute schedule.</p></details><details><summary>Can I verify a payout myself?</summary><p>Yes. A transaction hash can be checked with any public explorer that supports the relevant blockchain.</p></details><details><summary>Are listed firms endorsed?</summary><p>No. Inclusion is a record of tracked activity, not an endorsement or recommendation.</p></details></div></div>`}
function renderAbout(){document.querySelector('#payoutView').innerHTML=`<div class="payout-copy"><h3>How this payout hub works</h3><div class="about-steps"><article class="verify-step"><b>Track</b><p>Monitor supported on-chain payout methods across listed firms.</p></article><article class="verify-step"><b>Verify</b><p>Check transactions and token contracts against public blockchain records.</p></article><article class="verify-step"><b>Publish</b><p>Present totals, trends, and records in a comparable format.</p></article><article class="verify-step"><b>Exclude</b><p>Leave out claims and payment rails that cannot be independently tracked.</p></article></div><h3>Independent by design</h3><p>Paid placement does not influence the payout tables. A listing documents tracked settlements; it is not an endorsement of a firm, product, or offer.</p><h3>Using the data</h3><p>Figures update automatically and may not represent firms’ full payout volume. Use them alongside current firm rules and verified reviews.</p><span class="contact-placeholder">Contact us</span></div>`}
function renderPayoutView(){document.querySelectorAll('[data-payout-view]').forEach(b=>b.classList.toggle('on',b.dataset.payoutView===payoutView));if(!payoutHeader()){payoutEmpty();return}if(payoutView==='payouts'){if(payoutMode==='leaderboard')renderPayoutLeaderboard();else renderPayouts()}else if(payoutView==='statistics')renderStatistics();else if(payoutView==='weekly'||payoutView==='monthly')renderPeriod(payoutView);else if(payoutView==='records')renderRecords();else if(payoutView==='methodology')renderMethodology();else renderAbout()}

let compareSelections=['FundedNext','FundingPips','Alpha Capital',''];
function compareChallenge(name){return CHALLENGES_DATA.filter(x=>x.firm===name&&x.account_size==='100K'&&x.steps==='2 Steps').sort((a,b)=>Number(a.price)-Number(b.price)||Number(b.popularity)-Number(a.popularity))[0]||null}
function comparePayout(name,kind){const source=kind==='latest'?(PAYOUT_DATA.latest_24h||[]):(PAYOUT_DATA.monthly?.rows||[]);const row=source.find(x=>payoutCanonicalName(x.firm)===name);if(!row)return '—';return kind==='latest'?(row.total||'—'):(row.cells?.[2]||'—')}
function compareCell(value,detail=''){return `<div class="compare-value"><b>${value==null||value===''?'—':safe(value)}</b>${detail?`<span>${safe(detail)}</span>`:''}</div>`}
function renderCompare(){const marketFirms=sourceFirms(),choices=marketFirms.map(f=>f.name).sort((a,b)=>a.localeCompare(b));const cfc=document.querySelector('#compareFirmCount');if(cfc)cfc.textContent=choices.length;const ccc=document.querySelector('#compareChallengeCount');if(ccc)ccc.textContent=CHALLENGES_DATA.filter(x=>firmInMarket(x.firm)).length;const picker=document.querySelector('#comparePicker');if(!picker)return;picker.innerHTML=compareSelections.map((selected,index)=>`<label>Firm ${index+1}<select data-compare-slot="${index}"><option value="">Add a firm</option>${choices.map(name=>`<option value="${safe(name)}" ${name===selected?'selected':''} ${compareSelections.includes(name)&&name!==selected?'disabled':''}>${safe(name)}</option>`).join('')}</select></label>`).join('');const selected=compareSelections.filter(Boolean);const table=document.querySelector('#compareTable');if(!table)return;if(!selected.length){table.innerHTML=`<div class="compare-empty">Choose at least one ${marketLabel()} firm to begin the comparison.</div>`;return}const head=`<div class="compare-row"><div class="compare-label">Firm</div>${selected.map(name=>`<div class="compare-firm-head">${logo(name)}<div><strong>${safe(name)}</strong><span class="rating">${marketLabel()} comparison</span></div></div>`).join('')}</div>`;const rows=[['Trustpilot rating',name=>{const f=TRUSTPILOT_FIRMS.find(x=>x.name===name);return compareCell(f?.trustpilotRating==null?'—':`${f.trustpilotRating.toFixed(1)} / 5`,f?.trustpilotReviews==null?'—':`${Number(f.trustpilotReviews).toLocaleString()} reviews`)}],['Challenge price',name=>{const x=compareChallenge(name);return compareCell(x?challengeMoney(x,x.price):'—',x?'Lowest tracked 100K · 2 Steps':'Not tracked yet')}],['Profit target',name=>{const x=compareChallenge(name);return compareCell(x?.profit_target||'—')}],['Daily / max loss',name=>{const x=compareChallenge(name);return compareCell(x?`${x.daily_loss||'—'} / ${x.max_loss||'—'}`:'—',x?.max_loss_type||'Not tracked yet')}],['Profit split',name=>{const x=compareChallenge(name);return compareCell(x?.profit_split||'—')}],['Payout frequency',name=>{const x=compareChallenge(name);return compareCell(x?.payout_freq||'—')}],['Platforms',name=>{const f=marketFirms.find(x=>x.name===name);return compareCell(f?.platforms?.join(', ')||'—')}],['LENZ offer',name=>{const x=OFFER_CATALOG.find(o=>o.name===name);return x?`<div class="compare-value"><b>${safe(x.discount)}</b><span class="compare-code">LENZ</span></div>`:compareCell('—','Not tracked yet')}],['Latest 24h payouts',name=>compareCell(comparePayout(name,'latest'))],['Month-to-date payouts',name=>compareCell(comparePayout(name,'monthly'))]];table.style.setProperty('--compare-cols',selected.length);table.innerHTML=head+rows.map(([label,fn])=>`<div class="compare-row"><div class="compare-label">${label}</div>${selected.map(name=>fn(name)).join('')}</div>`).join('')}
