// Interactive Modal Handlers
document.addEventListener('submit', function(e) {
  if (e.target && e.target.id === 'vipAccessForm') {
    e.preventDefault();
    const email = document.getElementById('vipEmail')?.value;
    if (email) {
      try { localStorage.setItem('pfl_vip_user', email); } catch (_) {}
      const succ = document.getElementById('vipSuccess');
      if (succ) succ.style.display = 'block';
      setTimeout(() => { closeModals(); if (succ) succ.style.display = 'none'; showToast('VIP deal alerts activated!'); }, 1800);
    }
  }
  if (e.target && e.target.id === 'traderReviewForm') {
    e.preventDefault();
    const succ = document.getElementById('reviewSubmitSuccess');
    if (succ) succ.style.display = 'block';
    setTimeout(() => { closeModals(); if (succ) succ.style.display = 'none'; showToast('Trader review submitted for moderation!'); }, 1800);
  }
  if (e.target && e.target.id === 'delayReportForm') {
    e.preventDefault();
    const succ = document.getElementById('delayReportSuccess');
    if (succ) succ.style.display = 'block';
    setTimeout(() => { closeModals(); if (succ) succ.style.display = 'none'; showToast('Delay report logged for verification!'); }, 1800);
  }
});


/* ========================================================
   SCROLL ANIMATIONS & DYNAMIC HEADER CONTROLLER
   ======================================================== */
(function initScrollAnimations() {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;

  function bindScroll() {
    const header = document.querySelector('.site-head');
    const bar = document.getElementById('scrollProgressBar');
    const btt = document.getElementById('backToTopBtn');

    if (btt && !btt.onclick) {
      btt.onclick = () => window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    const onScroll = () => {
      const scrollY = window.scrollY || document.documentElement.scrollTop;
      const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
      const pct = maxScroll > 0 ? (scrollY / maxScroll) * 100 : 0;

      if (bar) bar.style.width = pct + '%';
      if (header) header.classList.toggle('scrolled', scrollY > 40);
      if (btt) btt.classList.toggle('is-visible', scrollY > 400);
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();

    // Scroll reveal observer
    const targets = document.querySelectorAll(
      '.section, #offers, #rankings, #resources, #videos, #faq, .panel, .futures-panel, .resource-card-3d, .rank-card, .payout-hub, .compare-page'
    );

    if ('IntersectionObserver' in window) {
      const observer = new IntersectionObserver((entries, obs) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            obs.unobserve(entry.target);
          }
        });
      }, {
        rootMargin: '0px 0px -30px 0px',
        threshold: 0.05
      });

      targets.forEach((el, index) => {
        el.classList.add('scroll-reveal');
        if (el.classList.contains('resource-card-3d') || el.classList.contains('rank-card')) {
          el.classList.add('stagger-' + ((index % 6) + 1));
        }
        observer.observe(el);
      });
    } else {
      targets.forEach(el => el.classList.add('is-visible'));
    }

    // Dynamic Mutation Observer for rankCards
    const observerTarget = document.querySelector('#rankList');
    if (observerTarget && window.MutationObserver) {
      const rankObserver = new MutationObserver(() => {
        document.querySelectorAll('#rankList .rank-card:not(.scroll-reveal)').forEach((card, idx) => {
          card.classList.add('scroll-reveal', 'stagger-' + ((idx % 6) + 1), 'is-visible');
        });
      });
      rankObserver.observe(observerTarget, { childList: true });
    }
  }

  // Live Payout Auto-Sync (polls backend feed every 60 seconds)
  function initLivePayoutFeed() {
    async function syncFeed() {
      try {
        const res = await fetch('/api/payouts');
        if (!res.ok) return;
        const fresh = await res.json();
        if (fresh && fresh.captured_at && fresh.captured_at !== PAYOUT_DATA.captured_at) {
          Object.assign(PAYOUT_DATA, fresh);
          if (typeof currentPage !== 'undefined' && currentPage === 'payouts') {
            if (typeof renderPayoutView === 'function') renderPayoutView();
          }
          if (typeof FOREX_NAMES !== 'undefined' && typeof payoutCanonicalName === 'function') {
            const forexCount = new Set([...(PAYOUT_DATA.latest_24h||[]),...(PAYOUT_DATA.weekly?.rows||[]),...(PAYOUT_DATA.monthly?.rows||[])]
              .filter(x => FOREX_NAMES.has(payoutCanonicalName(x.firm)))
              .map(x => payoutCanonicalName(x.firm))).size;
            const heroEl = document.querySelector('#heroPayoutFirmCount');
            if (heroEl) heroEl.textContent = forexCount.toLocaleString();
          }
        }
      } catch (_) {}
    }
    setInterval(syncFeed, 60000);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      bindScroll();
      initLivePayoutFeed();
    });
  } else {
    bindScroll();
    initLivePayoutFeed();
  }
})();
